part of '../../main.dart';

const List<Study> studyCatalog11 = <Study>[
Study(
    number: '81',
    title: "La nueva creación y el estado eterno: cielos nuevos, tierra nueva y la morada de Dios con su pueblo",
    subtitle: "Un estudio bíblico sobre la renovación de todas las cosas, la nueva Jerusalén y la comunión eterna de los redimidos con Dios.",
    introduction: "La esperanza bíblica alcanza su expresión culminante en la promesa de cielos nuevos y tierra nueva, donde mora la justicia y Dios habita con su pueblo. Aunque el estudio anterior examinó el juicio final y mencionó la renovación de todas las cosas, aquí la atención se concentra en el estado eterno y en la descripción bíblica de la nueva creación. Las Escrituras anuncian el fin de la muerte, el dolor y la maldición; la presencia permanente de Dios; la nueva Jerusalén; el río y el árbol de la vida; y el reinado de Dios y del Cordero. Estas imágenes deben estudiarse respetando el lenguaje profético y sin afirmar detalles que la Biblia no revela. La nueva creación no es una utopía construida por la humanidad ni una excusa para despreciar el mundo presente. Es la promesa de Dios de llevar su propósito creador y redentor a plenitud. Desde la perspectiva trinitaria, el Padre cumple su propósito, el Hijo aparece como el Cordero y centro de la ciudad, y el Espíritu sostiene la esperanza e invita a recibir gratuitamente el agua de vida. Esta esperanza fortalece la santidad, la perseverancia y la responsabilidad cristiana en el presente.",
    sections: [
      StudySection(title: "1. La promesa de una creación renovada", content: "La esperanza bíblica no termina con la eliminación del mal: Dios promete cielos nuevos y tierra nueva donde habite la justicia. Esta promesa orienta la mirada hacia la consumación de su propósito creador.", references: "Isaías 65:17; 2 Pedro 3:13; Apocalipsis 21:1"),
      StudySection(title: "2. La continuidad y transformación de la creación", content: "La nueva creación no debe imaginarse simplemente como el abandono de todo lo creado. La Escritura anuncia una renovación radical bajo el gobierno de Dios, aunque no explica todos los mecanismos de esa transformación.", references: "Romanos 8:19-23; 2 Pedro 3:10-13; Apocalipsis 21:5"),
      StudySection(title: "3. Cielos nuevos y tierra nueva", content: "La expresión bíblica señala el orden renovado que Dios establecerá. La creación será liberada de la corrupción y quedará plenamente sometida a la justicia divina.", references: "Isaías 66:22; 2 Pedro 3:13; Apocalipsis 21:1"),
      StudySection(title: "4. La morada de Dios con su pueblo", content: "La culminación de la esperanza es la comunión plena de Dios con los redimidos. La presencia divina ya no será experimentada bajo las limitaciones y aflicciones de la historia presente.", references: "Apocalipsis 21:3; Ezequiel 37:26-27; Zacarías 2:10-11"),
      StudySection(title: "5. La nueva Jerusalén", content: "Apocalipsis presenta la nueva Jerusalén como imagen de la comunidad redimida y de la presencia de Dios. La ciudad desciende de Dios; su seguridad y gloria proceden de Él, no del poder humano.", references: "Apocalipsis 21:2,9-14; Hebreos 11:10,16; 12:22"),
      StudySection(title: "6. La santidad de la ciudad", content: "La nueva Jerusalén es descrita como santa. La imagen comunica que la comunidad final estará completamente apartada para Dios y libre de la corrupción moral que caracteriza al pecado.", references: "Apocalipsis 21:2,10,27; Isaías 52:1; Zacarías 14:20-21"),
      StudySection(title: "7. La gloria de Dios como luz", content: "La ciudad no depende de las fuentes habituales de iluminación porque la gloria de Dios la alumbra y el Cordero es su lumbrera. El lenguaje expresa la presencia y el gobierno glorioso de Dios.", references: "Apocalipsis 21:23; 22:5; Isaías 60:19-20"),
      StudySection(title: "8. El Cordero y la luz de la ciudad", content: "Jesucristo, el Cordero, ocupa un lugar central en la visión de la ciudad. La gloria de Dios y la obra del Hijo no compiten: la revelación presenta al Cordero como luz de la comunidad redimida.", references: "Apocalipsis 21:22-23; Juan 1:4-9; Juan 8:12"),
      StudySection(title: "9. La ausencia del templo como edificio", content: "Juan declara que no vio templo en la ciudad, porque el Señor Dios Todopoderoso y el Cordero son su templo. La comunión con Dios será directa y plena, sin las estructuras provisionales del antiguo culto.", references: "Apocalipsis 21:22; Juan 4:21-24; Hebreos 9:11-12"),
      StudySection(title: "10. La presencia permanente de Dios", content: "La promesa de que Dios habitará con su pueblo anuncia una comunión estable y definitiva. Ya no habrá separación causada por el pecado ni distancia relacional como la que marca la historia presente.", references: "Apocalipsis 21:3; Levítico 26:11-12; 2 Corintios 6:16"),
      StudySection(title: "11. El fin de la muerte", content: "En la nueva creación la muerte ya no existirá. La promesa responde al enemigo que ha marcado la experiencia humana desde la caída y anuncia la plenitud de la victoria de Dios.", references: "Apocalipsis 21:4; 1 Corintios 15:26,54-57; Isaías 25:8"),
      StudySection(title: "12. El fin del duelo y del dolor", content: "Dios enjugará toda lágrima y terminarán el luto, el clamor y el dolor. La esperanza futura no minimiza el sufrimiento actual; asegura que no será eterno ni tendrá la última palabra.", references: "Apocalipsis 21:4; Isaías 35:10; 65:19"),
      StudySection(title: "13. La desaparición de las cosas primeras", content: "La expresión sobre las cosas primeras señala el cierre del orden marcado por pecado, muerte y sufrimiento. Dios hace nuevas todas las cosas y lleva su propósito a plenitud.", references: "Apocalipsis 21:4-5; 2 Corintios 5:17; Isaías 43:18-19"),
      StudySection(title: "14. La promesa: he aquí, yo hago nuevas todas las cosas", content: "La renovación procede de la iniciativa soberana de Dios. No es el resultado del progreso humano ni de una utopía construida por la sociedad, sino del acto creador del Señor.", references: "Apocalipsis 21:5; Isaías 42:9; 2 Pedro 3:13"),
      StudySection(title: "15. La fidelidad de Dios a sus promesas", content: "La esperanza de la nueva creación descansa en la fidelidad del Dios que promete. Sus palabras son verdaderas y dignas de confianza, incluso cuando su cumplimiento completo todavía se espera.", references: "Apocalipsis 21:5-6; Números 23:19; Tito 1:2"),
      StudySection(title: "16. El agua de vida", content: "La invitación a recibir gratuitamente del agua de la vida representa la satisfacción y vida que Dios concede. La plenitud futura es don de gracia, no recompensa comprada por méritos humanos.", references: "Apocalipsis 21:6; 22:17; Juan 4:10-14"),
      StudySection(title: "17. La herencia de los vencedores", content: "Dios promete herencia a quienes vencen y perseveran en fidelidad. La victoria cristiana no es autosuficiencia, sino permanecer en Cristo confiando en la gracia de Dios.", references: "Apocalipsis 21:7; Romanos 8:16-17; 1 Juan 5:4-5"),
      StudySection(title: "18. La identidad de los hijos de Dios", content: "La promesa de que Dios será Dios de su pueblo y ellos serán sus hijos expresa la consumación de la relación filial. La adopción recibida ahora alcanzará su manifestación plena.", references: "Apocalipsis 21:7; Romanos 8:15-17,23; 1 Juan 3:1-2"),
      StudySection(title: "19. La exclusión de la maldad persistente", content: "Apocalipsis afirma que nada inmundo entrará en la ciudad. La nueva creación no será una continuación de la rebelión, sino el ámbito de la justicia y santidad de Dios.", references: "Apocalipsis 21:8,27; 1 Corintios 6:9-11; Gálatas 5:19-21"),
      StudySection(title: "20. La pureza de la comunidad redimida", content: "La comunidad final estará libre de engaño, idolatría y maldad. Esta promesa llama desde ahora a vivir en verdad y a rechazar prácticas incompatibles con el reino de Dios.", references: "Apocalipsis 21:27; Efesios 5:5-11; 1 Juan 3:2-3"),
      StudySection(title: "21. La visión del río de agua de vida", content: "El río que sale del trono de Dios y del Cordero representa la vida que procede del gobierno divino. La imagen retoma promesas proféticas de restauración y abundancia.", references: "Apocalipsis 22:1; Ezequiel 47:1-12; Zacarías 14:8"),
      StudySection(title: "22. El árbol de la vida", content: "El árbol de la vida aparece nuevamente en la visión final. Lo que se perdió por la entrada del pecado es presentado ahora en un escenario de vida y comunión bajo la gracia de Dios.", references: "Génesis 2:9; 3:22-24; Apocalipsis 22:2,14"),
      StudySection(title: "23. La sanidad de las naciones", content: "Las hojas del árbol se relacionan con la sanidad de las naciones. La imagen anuncia restauración completa y excluye la hostilidad y la maldición que han dividido a los pueblos.", references: "Apocalipsis 22:2; Isaías 2:2-4; 60:1-5"),
      StudySection(title: "24. La ausencia de maldición", content: "La maldición ya no estará presente. La creación y la vida humana serán liberadas de las consecuencias del pecado, conforme al propósito restaurador de Dios.", references: "Apocalipsis 22:3; Génesis 3:14-19; Romanos 8:20-21"),
      StudySection(title: "25. El trono de Dios y del Cordero", content: "El trono expresa el gobierno soberano de Dios y del Cordero. La visión mantiene la distinción personal entre Dios y el Cordero y presenta su reinado unido e incontestable.", references: "Apocalipsis 22:1,3; 5:6-13; 7:10"),
      StudySection(title: "26. El servicio y la adoración eterna", content: "Los siervos de Dios le servirán y su servicio estará libre de frustración, corrupción y pecado. La eternidad no se presenta como inactividad vacía, sino como comunión y servicio gozoso.", references: "Apocalipsis 22:3; 7:15; 1 Corintios 13:12"),
      StudySection(title: "27. El rostro de Dios", content: "La promesa de ver el rostro de Dios expresa la intimidad y comunión que alcanzará su plenitud. La visión debe entenderse a la luz de la santidad divina y de la obra redentora.", references: "Apocalipsis 22:4; Mateo 5:8; 1 Juan 3:2"),
      StudySection(title: "28. El nombre de Dios en sus siervos", content: "El nombre en la frente simboliza pertenencia, identidad y lealtad al Señor. Los redimidos estarán plenamente identificados como pueblo suyo.", references: "Apocalipsis 22:4; 3:12; 14:1"),
      StudySection(title: "29. El reinado de los redimidos", content: "La Escritura afirma que los siervos de Dios reinarán por los siglos. Esta participación no convierte a los redimidos en divinidades; es una responsabilidad concedida bajo la autoridad del Señor.", references: "Apocalipsis 22:5; Daniel 7:18,27; 2 Timoteo 2:12"),
      StudySection(title: "30. La nueva creación y el propósito original", content: "La esperanza final guarda relación con el propósito de Dios al crear al ser humano y darle responsabilidad sobre la tierra. La restauración supera la ruina del pecado y manifiesta el buen propósito del Creador.", references: "Génesis 1:26-28; Salmos 8:4-8; Apocalipsis 22:3-5"),
      StudySection(title: "31. La creación liberada de corrupción", content: "Pablo describe a la creación esperando ser liberada de la esclavitud de corrupción. La esperanza futura incluye el mundo creado y no solamente la experiencia interior de los creyentes.", references: "Romanos 8:19-23; Isaías 11:6-9; 2 Pedro 3:13"),
      StudySection(title: "32. La redención del cuerpo y la esperanza futura", content: "La esperanza cristiana incluye la redención del cuerpo. La nueva creación no debe reducirse a una existencia incorpórea; Dios lleva a plenitud su obra redentora sobre la persona completa.", references: "Romanos 8:23; Filipenses 3:20-21; 1 Corintios 15:42-49"),
      StudySection(title: "33. La justicia como característica del mundo venidero", content: "Pedro anuncia cielos nuevos y tierra nueva en los cuales mora la justicia. La nueva realidad estará completamente de acuerdo con el carácter santo de Dios.", references: "2 Pedro 3:13; Isaías 32:16-18; Apocalipsis 21:27"),
      StudySection(title: "34. La paz y la reconciliación de la creación", content: "Los profetas describen una realidad de paz bajo el gobierno de Dios. Estas imágenes anuncian el fin de la violencia y la armonía de la creación restaurada.", references: "Isaías 11:6-9; 65:25; Colosenses 1:19-20"),
      StudySection(title: "35. La comunión de pueblos y naciones", content: "La visión incluye naciones que caminan a la luz de la gloria de Dios y llevan su honor a la ciudad. La diversidad de pueblos no desaparece, sino que queda bajo el señorío justo del Señor.", references: "Apocalipsis 21:24-26; Isaías 60:3-11; Daniel 7:14"),
      StudySection(title: "36. La gloria de las naciones sometida a Dios", content: "La gloria y los recursos de las naciones son presentados bajo la autoridad de Dios. Ninguna cultura ni poder humano será objeto de adoración; todo honor legítimo se ordenará hacia el Señor.", references: "Apocalipsis 21:24-26; Salmos 86:9; Isaías 60:5-7"),
      StudySection(title: "37. La ausencia de noche y la seguridad eterna", content: "La ausencia de noche en la ciudad comunica luz y seguridad permanentes. No habrá amenaza, ocultamiento ni temor que interrumpa la comunión con Dios.", references: "Apocalipsis 21:25; 22:5; Zacarías 14:7"),
      StudySection(title: "38. La nueva creación como cumplimiento profético", content: "Las promesas de restauración anunciadas por los profetas encuentran su horizonte en la nueva creación. La lectura cristiana reconoce su cumplimiento en el propósito de Dios revelado en Cristo.", references: "Isaías 65:17-25; 66:22-23; 2 Pedro 3:13"),
      StudySection(title: "39. La esperanza futura y la vida presente", content: "Esperar la nueva creación no conduce a despreciar el mundo actual. Motiva a cuidar la creación, practicar justicia y vivir de manera coherente con el futuro prometido.", references: "2 Pedro 3:11-14; Romanos 8:24-25; Colosenses 3:1-4"),
      StudySection(title: "40. La perseverancia en medio del sufrimiento", content: "La promesa de un mundo sin dolor fortalece a quienes sufren en el presente. La esperanza cristiana permite perseverar sin llamar bueno al sufrimiento ni considerarlo definitivo.", references: "Romanos 8:18; 2 Corintios 4:16-18; Apocalipsis 21:4"),
      StudySection(title: "41. La nueva creación y la santidad de la Iglesia", content: "Quien espera estar con Dios en santidad debe buscar la santidad ahora. La esperanza futura purifica las motivaciones y orienta las decisiones cotidianas.", references: "1 Juan 3:2-3; 2 Pedro 3:14; Hebreos 12:14"),
      StudySection(title: "42. La responsabilidad ecológica a la luz de la esperanza", content: "La promesa de renovación no justifica destruir ni despreciar la creación. El ser humano sigue llamado a ejercer una mayordomía responsable mientras espera la restauración que solo Dios consumará.", references: "Génesis 2:15; Salmos 24:1; Romanos 8:19-22"),
      StudySection(title: "43. La esperanza no es una utopía humana", content: "La nueva creación no será construida por la capacidad política, tecnológica o moral de la humanidad. Es una promesa divina que orienta el trabajo presente sin confundirlo con la consumación del reino.", references: "Hebreos 11:10,16; 2 Pedro 3:13; Apocalipsis 21:1-5"),
      StudySection(title: "44. La Trinidad y la consumación de la nueva creación", content: "La esperanza final se comprende dentro de la obra del único Dios: el Padre lleva a cumplimiento su propósito, el Hijo es el Cordero y centro de la ciudad, y el Espíritu aparece en la invitación a recibir el agua de vida. Las personas divinas no se confunden ni se dividen en la obra de salvación.", references: "Apocalipsis 21:22-23; 22:1,17; Efesios 1:9-14"),
      StudySection(title: "45. El Espíritu y la esperanza de la herencia", content: "El Espíritu Santo es las arras de la herencia del creyente. Su presencia actual confirma que la salvación será llevada a su plenitud y sostiene la esperanza mientras aguardamos la redención completa.", references: "Efesios 1:13-14; Romanos 8:23; 2 Corintios 1:21-22"),
      StudySection(title: "46. El Cordero como centro de la adoración eterna", content: "La nueva Jerusalén está vinculada inseparablemente con Dios y el Cordero. La adoración final reconoce la obra redentora de Jesucristo y la dignidad que le corresponde.", references: "Apocalipsis 5:9-14; 7:9-12; 21:22-23"),
      StudySection(title: "47. La certeza de las palabras proféticas", content: "La visión concluye afirmando la fidelidad de las palabras reveladas. La Iglesia debe recibirlas con reverencia, sin añadir especulaciones ni convertir símbolos proféticos en afirmaciones que el texto no hace.", references: "Apocalipsis 22:6-7,18-19; 2 Pedro 1:19-21"),
      StudySection(title: "48. La invitación del Espíritu y la Iglesia", content: "El Espíritu y la esposa dicen: Ven. La Iglesia, sostenida por el Espíritu, mantiene viva la esperanza del cumplimiento de la promesa y anuncia la invitación de Dios a recibir gratuitamente la vida.", references: "Apocalipsis 22:17; Romanos 8:26-27; 1 Corintios 1:7"),
      StudySection(title: "49. La esperanza que impulsa fidelidad hasta el fin", content: "La expectativa de la nueva creación llama a permanecer firmes, servir al Señor y no abandonar la fe. La promesa de Dios da sentido a la perseverancia y al trabajo cristiano.", references: "1 Corintios 15:58; Hebreos 10:23; Apocalipsis 22:12"),
      StudySection(title: "50. La plenitud de la comunión con Dios", content: "La meta de la esperanza no es solamente un lugar sin sufrimiento, sino la comunión plena con Dios. Su pueblo verá su rostro, le servirá y participará de la vida que procede de Él.", references: "Apocalipsis 21:3-4; 22:3-5; 1 Tesalonicenses 4:17"),
    ],
    conclusion: "La nueva creación es la consumación de la esperanza bíblica: Dios hará nuevas todas las cosas, habitará con su pueblo y eliminará definitivamente la muerte, el duelo, el clamor y el dolor. La nueva Jerusalén representa la comunidad santa que vive en la presencia de Dios y del Cordero. El río y el árbol de la vida anuncian la abundancia que procede del Señor; la ausencia de maldición proclama que el pecado y sus consecuencias no dominarán el orden eterno. La promesa incluye la creación liberada de corrupción y la redención plena de los hijos de Dios. No conocemos todos los detalles de esa realidad, por lo que debemos evitar especulaciones y permanecer fieles a lo revelado. Esta esperanza no nos lleva a abandonar nuestras responsabilidades presentes, sino a vivir con santidad, justicia, misericordia y cuidado de la creación. El Padre llevará a cumplimiento su propósito, Jesucristo será reconocido como el Cordero digno y el Espíritu sostendrá a la Iglesia en la esperanza. La meta final no es solamente vivir sin sufrimiento, sino disfrutar para siempre de la comunión plena con el Dios trino.",
  ),
Study(
    number: '82',
    title: "La ley de Dios: propósito, cumplimiento en Cristo y vida bajo la gracia",
    subtitle: "Un análisis bíblico de la ley mosaica, su propósito, su cumplimiento en Jesucristo y la obediencia cristiana bajo la gracia.",
    introduction: "La ley de Dios ocupa un lugar importante en la historia bíblica. Fue dada a Israel dentro del pacto del Sinaí y reguló su adoración, su vida comunitaria y su responsabilidad moral. Sus mandamientos revelan la santidad y justicia del Señor, pero también ponen de manifiesto el pecado y la incapacidad humana para alcanzar justificación mediante sus propias obras.\n\nEl Nuevo Testamento no presenta a Jesucristo como enemigo de la ley: Él vino a cumplirla y a llevar a su propósito la historia de la redención. Por medio de su muerte y resurrección, inaugura el nuevo pacto; la salvación se recibe por gracia mediante la fe, y el Espíritu Santo transforma al creyente para vivir en obediencia.\n\nEste estudio distingue la función histórica de las disposiciones del pacto mosaico, la continuidad de la voluntad moral de Dios y la libertad cristiana. Evita dos extremos: convertir la observancia de la ley en medio de justificación o utilizar la gracia como excusa para el pecado. Desde la perspectiva trinitaria, el Padre llama a la santidad, el Hijo cumple la voluntad divina y el Espíritu capacita para una vida nueva, sin confundir sus personas ni dividir la única obra de Dios.",
    sections: [
      StudySection(title: "1. La ley revela la voluntad moral de Dios", content: "La ley comunica lo que el Señor considera justo y bueno. No es un medio para comprar su favor; debe comprenderse dentro del pacto y la historia de la redención.", references: "Salmos 19:7-11; Romanos 7:12"),
      StudySection(title: "2. El carácter santo del Legislador", content: "La autoridad de la ley procede del carácter del Señor. Sus mandamientos expresan santidad y justicia; obedecer es responder con reverencia, no buscar superioridad.", references: "Levítico 19:1-2; Salmos 99:4"),
      StudySection(title: "3. La ley después de la liberación de Egipto", content: "Dios dio sus mandamientos después de liberar a Israel. La obediencia no fue el precio de la liberación, sino la respuesta del pueblo rescatado.", references: "Éxodo 19:3-6; Éxodo 20:1-2"),
      StudySection(title: "4. El pacto del Sinaí", content: "Israel recibió mandamientos como pueblo del pacto. La ley regulaba su adoración y vida comunitaria, distinguiéndolo como pueblo perteneciente al Señor.", references: "Éxodo 19:5-8; Éxodo 24:3-8"),
      StudySection(title: "5. Las disposiciones morales, civiles y ceremoniales", content: "La ley contiene disposiciones con funciones distintas dentro de la alianza con Israel. Reconocerlas permite interpretar su contexto y cumplimiento en Cristo.", references: "Éxodo 20–23; Levítico 1–7; Hebreos 9:1-10"),
      StudySection(title: "6. Los Diez Mandamientos", content: "Los Diez Mandamientos regulan la adoración, la familia, la verdad y el respeto al prójimo. Unen la lealtad a Dios con la responsabilidad hacia los demás.", references: "Éxodo 20:1-17; Deuteronomio 5:6-21"),
      StudySection(title: "7. Amar a Dios con todo el ser", content: "El mandamiento principal exige lealtad integral al Señor. Jesús confirmó que este amor ocupa el primer lugar y orienta toda la vida del discípulo.", references: "Deuteronomio 6:4-5; Mateo 22:37-38"),
      StudySection(title: "8. Amar al prójimo", content: "La ley exige tratar al prójimo con justicia y amor. Jesús unió este mandamiento al amor a Dios, mostrando que la devoción no se separa del trato digno.", references: "Levítico 19:18; Mateo 22:39-40"),
      StudySection(title: "9. La protección de la vida", content: "La prohibición del homicidio enseña respeto por la vida. Jesús profundizó su alcance al confrontar el odio y llamar a buscar reconciliación.", references: "Éxodo 20:13; Mateo 5:21-24"),
      StudySection(title: "10. Fidelidad y pureza", content: "La prohibición del adulterio protege la fidelidad. Jesús enseñó que la pureza también compromete las intenciones del corazón.", references: "Éxodo 20:14; Mateo 5:27-28"),
      StudySection(title: "11. La verdad y el testimonio", content: "La prohibición del falso testimonio protege la justicia y la reputación del prójimo. El pueblo de Dios debe evitar calumnia, manipulación y engaño.", references: "Éxodo 20:16; Efesios 4:25"),
      StudySection(title: "12. Propiedad y contentamiento", content: "Los mandamientos contra el robo y la codicia confrontan la explotación. La justicia incluye honestidad y respeto por los bienes ajenos.", references: "Éxodo 20:15,17; Efesios 4:28"),
      StudySection(title: "13. El sábado en el pacto con Israel", content: "El sábado fue señal y ritmo de descanso dentro de la alianza mosaica, relacionado con creación y liberación. Su aplicación cristiana requiere considerar el contexto del pacto.", references: "Éxodo 20:8-11; Deuteronomio 5:12-15"),
      StudySection(title: "14. Sacrificios y ceremonias", content: "Los sacrificios enseñaban acerca de santidad, culpa y expiación. Hebreos explica que señalaban la obra superior y definitiva de Jesucristo.", references: "Levítico 16; Hebreos 9:1-14; 10:1-14"),
      StudySection(title: "15. Pureza ritual y transformación interior", content: "Las normas de pureza distinguían situaciones rituales en Israel. Jesús y los apóstoles explican la pureza a la luz de Cristo y de la transformación interior.", references: "Levítico 11–15; Marcos 7:14-23; Hechos 10:9-16"),
      StudySection(title: "16. Justicia civil en Israel", content: "Las disposiciones civiles regulaban conflictos, propiedad y protección de vulnerables. Sus principios revelan preocupación por la justicia, aunque no son automáticamente el código de cada nación actual.", references: "Éxodo 21–23; Deuteronomio 16:18-20"),
      StudySection(title: "17. Cuidado del extranjero y del vulnerable", content: "Dios prohibió aprovecharse del extranjero, la viuda, el huérfano y el pobre. La obediencia debía expresarse en justicia y protección de quienes carecían de poder.", references: "Éxodo 22:21-27; Levítico 19:9-10"),
      StudySection(title: "18. La ley revela el pecado", content: "La ley hace visible la transgresión al nombrar lo que contradice la voluntad divina. No crea la maldad: la descubre y muestra la necesidad de redención.", references: "Romanos 3:19-20; Romanos 7:7-13"),
      StudySection(title: "19. La incapacidad de justificarse por la ley", content: "La ley es buena, pero el pecado impide alcanzar justicia mediante esfuerzos humanos. Su función no es ofrecer méritos salvadores, sino evidenciar la necesidad de gracia.", references: "Romanos 3:20-24; Gálatas 2:16"),
      StudySection(title: "20. La ley y la promesa a Abraham", content: "La ley no anuló la promesa anterior. La herencia depende de la promesa de Dios y se recibe por fe, no por mérito humano.", references: "Génesis 15:1-6; Gálatas 3:15-18"),
      StudySection(title: "21. La función pedagógica de la ley", content: "Pablo presenta la ley como tutor que condujo a reconocer la necesidad de Cristo. Esta imagen explica una función histórica, no desacredita la santidad de los mandamientos.", references: "Gálatas 3:23-25; Romanos 7:12"),
      StudySection(title: "22. Jesús cumple la ley", content: "Jesús declaró que no vino a abolir la Ley y los Profetas, sino a cumplirlos. Su vida, enseñanza y obra llevan la historia bíblica a su propósito.", references: "Mateo 5:17-20; Lucas 24:44-47"),
      StudySection(title: "23. La autoridad de Jesús para interpretar la ley", content: "En el Sermón del Monte, Jesús expone la profundidad de los mandamientos y confronta interpretaciones superficiales, revelando su alcance en motivaciones y relaciones.", references: "Mateo 5:21-48; Mateo 7:28-29"),
      StudySection(title: "24. El amor cumple la intención de la ley", content: "El amor no reemplaza la verdad ni vuelve opcionales los mandamientos. Quien ama al prójimo no busca dañarlo ni explotarlo.", references: "Romanos 13:8-10; Gálatas 5:13-14"),
      StudySection(title: "25. Cristo y la maldición de la ley", content: "La maldición se relaciona con la condena que acompaña la transgresión. Cristo asumió esa carga para que la bendición llegara a las naciones y recibieran el Espíritu por fe.", references: "Gálatas 3:10-14; Deuteronomio 21:22-23"),
      StudySection(title: "26. La justicia manifestada aparte de las obras de la ley", content: "La justicia de Dios se manifestó aparte de las obras de la ley, aunque cuenta con el testimonio de la Ley y los Profetas. Se recibe por la fe en Jesucristo.", references: "Romanos 3:21-26; Filipenses 3:9"),
      StudySection(title: "27. La ley escrita en el corazón", content: "El nuevo pacto anuncia transformación interior: Dios escribe su ley en el corazón. No es conformidad externa, sino obediencia nacida de su obra.", references: "Jeremías 31:31-34; Ezequiel 36:26-27"),
      StudySection(title: "28. El Espíritu capacita para obedecer", content: "La vida cristiana no depende solo de fuerza de voluntad. El Espíritu Santo obra en los creyentes para producir una vida que agrada a Dios.", references: "Romanos 8:3-4; Gálatas 5:16-25"),
      StudySection(title: "29. La ley de Cristo y el servicio", content: "Pablo habla de la ley de Cristo al llamar a llevar las cargas de otros. La libertad no es egoísmo, sino vida guiada por el amor y el ejemplo del Señor.", references: "Gálatas 6:2; Juan 13:34-35"),
      StudySection(title: "30. La gracia no autoriza a pecar", content: "La gracia no permite persistir en la maldad. Pablo rechaza continuar en pecado para que la gracia abunde y enseña una vida nueva.", references: "Romanos 6:1-4,12-18; Gálatas 5:13"),
      StudySection(title: "31. Legalismo y obediencia genuina", content: "El legalismo busca mérito o superioridad mediante reglas. La obediencia cristiana nace de la fe, la gratitud y la dependencia de la gracia.", references: "Lucas 18:9-14; Gálatas 2:16; Efesios 2:8-10"),
      StudySection(title: "32. Libertad sin desprecio de los mandamientos", content: "La libertad en Cristo no significa indiferencia moral. El creyente no se justifica por la ley, pero vive en justicia, dominio propio y amor.", references: "Romanos 6:15-18; Santiago 1:22-25"),
      StudySection(title: "33. Días y alimentos en la comunidad cristiana", content: "El Nuevo Testamento enseña a no juzgar por disputas sobre comidas o días. La conciencia debe actuar delante del Señor, sin convertir preferencias en requisitos de salvación.", references: "Romanos 14:1-13; Colosenses 2:16-17"),
      StudySection(title: "34. La circuncisión como señal del pacto", content: "La circuncisión fue señal del pacto con Abraham. Los apóstoles rechazaron imponerla como condición de salvación a los creyentes gentiles en Cristo.", references: "Génesis 17:9-14; Hechos 15:1-29"),
      StudySection(title: "35. El concilio de Jerusalén", content: "La Iglesia discernió cómo recibir a los gentiles sin imponerles la ley mosaica como medio de salvación. La decisión protegió el evangelio y la comunión.", references: "Hechos 15:5-29; Gálatas 2:1-10"),
      StudySection(title: "36. La conciencia debe formarse con la Palabra", content: "La conciencia puede dar testimonio moral, pero no es infalible ni sustituye la revelación. Debe formarse con la Escritura y no imponer convicciones humanas como mandamientos divinos.", references: "Romanos 2:14-16; Romanos 14:22-23"),
      StudySection(title: "37. Justicia en la comunidad cristiana", content: "La imparcialidad, la verdad y el cuidado del vulnerable orientan a la Iglesia. Las comunidades deben resolver conflictos con justicia y evitar favoritismos.", references: "Santiago 2:1-9; Mateo 18:15-17"),
      StudySection(title: "38. La ley y las autoridades civiles", content: "El Nuevo Testamento reconoce la función de las autoridades, pero no las convierte en autoridad suprema sobre la conciencia. No se debe obedecer una orden que exija desobedecer a Dios.", references: "Romanos 13:1-7; Hechos 5:29"),
      StudySection(title: "39. La denuncia profética de la injusticia", content: "Los profetas denunciaron la religión que mantenía ceremonias mientras practicaba injusticia. El culto sin justicia y misericordia contradice la voluntad divina.", references: "Isaías 1:10-17; Miqueas 6:6-8; Amós 5:21-24"),
      StudySection(title: "40. El resumen de la ley y los profetas", content: "Al resumir la ley en el amor a Dios y al prójimo, Jesús mostró la unidad de la voluntad divina. El resumen revela la orientación esencial de los mandamientos.", references: "Mateo 22:34-40; Lucas 10:25-28"),
      StudySection(title: "41. La ley y la sabiduría cotidiana", content: "Los mandamientos y la literatura sapiencial enseñan prudencia, honestidad y responsabilidad. La sabiduría aplica la verdad de Dios a decisiones concretas.", references: "Proverbios 1:7-9; Salmos 119:97-105"),
      StudySection(title: "42. La Escritura guía al discípulo", content: "El creyente debe estudiar la Escritura con atención, comprender su contexto y practicarla. La obediencia madura somete la vida a la enseñanza completa de Dios.", references: "2 Timoteo 3:16-17; Hechos 17:11; Santiago 1:22-25"),
      StudySection(title: "43. La ley no puede justificar ni regenerar", content: "La ley señala el bien y denuncia el pecado, pero no regenera ni justifica. La salvación es obra de la gracia de Dios en Cristo y se recibe mediante la fe.", references: "Romanos 3:19-28; Gálatas 2:16; Efesios 2:8-9"),
      StudySection(title: "44. La obediencia como fruto de la salvación", content: "Las buenas obras no son la raíz de la salvación, sino su fruto. Dios salva por gracia y crea en Cristo un pueblo dispuesto a practicar lo bueno.", references: "Efesios 2:8-10; Tito 2:11-14; Tito 3:4-8"),
      StudySection(title: "45. La obra trinitaria en la obediencia cristiana", content: "El Padre llama a la santidad; el Hijo cumple la voluntad del Padre y es modelo de obediencia; el Espíritu transforma al creyente. Estas distinciones no dividen la obra del único Dios.", references: "Juan 6:38; Juan 14:26; Romanos 8:3-4; 1 Pedro 1:2"),
      StudySection(title: "46. La obediencia perfecta de Jesucristo", content: "Jesucristo obedeció perfectamente al Padre y su obra constituye el fundamento de la justicia recibida por fe. El creyente depende de la obra suficiente del Hijo.", references: "Romanos 5:18-19; Filipenses 2:8; 2 Corintios 5:21"),
      StudySection(title: "47. La ley y la santidad práctica", content: "La gracia enseña a renunciar a la impiedad y vivir con justicia. La santidad no consiste en fabricar reglas para aparentar superioridad, sino en pertenecer a Dios.", references: "Tito 2:11-14; 1 Pedro 1:14-16"),
      StudySection(title: "48. Evitar el legalismo y el libertinaje", content: "La Iglesia debe evitar imponer la ley mosaica como requisito de justificación y usar la gracia para justificar el pecado. El evangelio une salvación gratuita y vida transformada.", references: "Gálatas 5:1-6; Romanos 6:1-14; Santiago 2:14-18"),
      StudySection(title: "49. Vivir para agradar a Dios en el nuevo pacto", content: "La voluntad moral de Dios no es una carga arbitraria para quienes han sido reconciliados. En Cristo, el creyente sirve en novedad del Espíritu y espera la consumación de la justicia.", references: "Romanos 7:4-6; Romanos 8:1-4; Apocalipsis 21:1-4"),
      StudySection(title: "50. La obediencia como testimonio ante el mundo", content: "Una comunidad transformada demuestra que la gracia produce fruto visible. La conducta cristiana debe adornar el evangelio y conducir a otros a glorificar al Padre.", references: "Mateo 5:14-16; Tito 2:7-10; 1 Pedro 2:12"),
    ],
    conclusion: "La ley de Dios revela su carácter santo y justo, ordenó la vida de Israel dentro del antiguo pacto y mostró la gravedad del pecado. Sus disposiciones ceremoniales, civiles y morales deben interpretarse respetando su contexto y la historia de la redención. Jesucristo no vino a desechar las Escrituras, sino a cumplirlas; mediante su obra redentora abrió el nuevo pacto prometido. Nadie es justificado por las obras de la ley: la salvación es un regalo de gracia recibido por la fe. Sin embargo, la gracia no conduce a la indiferencia moral. El Espíritu Santo transforma al creyente para amar a Dios, servir al prójimo y practicar la justicia. La obediencia es fruto de la salvación, no su precio. El Padre llama a su pueblo, el Hijo es el cumplimiento y modelo perfecto de obediencia, y el Espíritu capacita para andar conforme a la voluntad divina. La Iglesia debe rechazar tanto el legalismo como el libertinaje y vivir en la libertad responsable de quienes están en Cristo."
  ),
Study(
    number: '83',
    title: 'La inspiración de las Escrituras: origen divino, autores humanos y autoridad de la Palabra',
    subtitle: 'La inspiración divina, la participación de los autores humanos y la autoridad de la Palabra para la fe y la vida cristiana.',
    introduction: '''La Biblia ocupa un lugar fundamental en la fe cristiana porque por medio de ella Dios ha dado testimonio de su carácter, sus obras y su propósito redentor. La Iglesia no puede construir su doctrina sobre impresiones personales, costumbres cambiantes o razonamientos separados de la revelación divina.

La doctrina de la inspiración afirma que las Escrituras proceden de Dios y que el Espíritu Santo obró mediante autores humanos para comunicar su mensaje. Esta afirmación no elimina la historia, la personalidad, el idioma ni el estilo de los escritores. Tampoco significa que toda interpretación humana sea infalible. Es necesario distinguir entre el texto inspirado y nuestras explicaciones, traducciones y aplicaciones.

Este estudio examina la inspiración, la autoridad, la transmisión, la interpretación y el uso de las Escrituras. También considera la obra del Padre, del Hijo y del Espíritu Santo en la revelación, manteniendo la confesión de un solo Dios en tres personas.''',
    sections: [
      StudySection(title: '1. Origen divino', content: 'La Escritura afirma que su mensaje procede de Dios. Su autoridad no descansa solo en la antigüedad o prestigio de sus escritores, sino en Aquel que se da a conocer por medio de ella.', references: '2 Timoteo 3:16; 2 Pedro 1:20-21.'),
      StudySection(title: '2. Significado de inspiración', content: 'Inspiración expresa que Dios es la fuente de la Escritura. No equivale a creatividad humana extraordinaria ni a entusiasmo religioso subjetivo, sino a la acción divina en la comunicación escrita de su mensaje.', references: '2 Timoteo 3:16; 2 Samuel 23:2.'),
      StudySection(title: '3. Autores humanos', content: 'Los libros bíblicos fueron escritos por personas reales, en idiomas y circunstancias diferentes. Dios obró por medio de ellas sin borrar su personalidad, formación ni contexto histórico.', references: 'Lucas 1:1-4; Jeremías 1:1-9.'),
      StudySection(title: '4. El Espíritu Santo y la inspiración', content: 'Pedro enseña que los hombres hablaron de parte de Dios impulsados por el Espíritu Santo. El Espíritu es presentado como persona divina que enseña y guía; su obra forma parte de la acción del único Dios trino.', references: '2 Pedro 1:20-21; Juan 14:26; 1 Corintios 2:10-13.'),
      StudySection(title: '5. Estilo de los escritores', content: 'Los autores conservaron diferencias de vocabulario, estructura y estilo. La inspiración no exige que todos escriban igual ni que sean instrumentos mecánicos; Dios utilizó sus capacidades para comunicar su verdad.', references: 'Lucas 1:1-4; Romanos 16:22.'),
      StudySection(title: '6. Contexto histórico', content: 'Los libros bíblicos están vinculados con acontecimientos, pueblos y lugares concretos. Conocer ese contexto ayuda a comprender el mensaje y evita separar la Escritura de la historia en que fue comunicada.', references: 'Lucas 2:1-2; Hechos 11:28.'),
      StudySection(title: '7. Géneros literarios', content: 'La Biblia contiene narración, poesía, proverbios, profecía, evangelios, cartas y literatura apocalíptica. Cada género comunica de manera particular y debe interpretarse conforme a sus características.', references: 'Salmos 19:1-6; Proverbios 1:1-7; Apocalipsis 1:1-3.'),
      StudySection(title: '8. Veracidad de Dios', content: 'Dios es veraz y su Palabra merece confianza. La veracidad debe entenderse según lo que cada pasaje realmente afirma, su intención y su género, sin atribuirle afirmaciones que no pretende realizar.', references: 'Números 23:19; Juan 17:17; Tito 1:2.'),
      StudySection(title: '9. Autoridad de la Escritura', content: 'La Escritura posee autoridad porque comunica la Palabra de Dios. Ninguna preferencia, tradición o autoridad humana puede colocarse por encima de lo revelado; la enseñanza de la Iglesia debe examinarse a su luz.', references: 'Mateo 4:4,7,10; Marcos 7:6-13.'),
      StudySection(title: '10. Suficiencia', content: 'La Biblia proporciona lo necesario para conocer el mensaje de salvación y vivir fielmente. Su suficiencia no significa que contenga todos los datos de cada disciplina, sino que cumple el propósito revelador y formativo que Dios le asignó.', references: '2 Timoteo 3:15-17; Salmos 19:7-11.'),
      StudySection(title: '11. Claridad', content: 'El mensaje central de la salvación se comunica de manera comprensible. Esto no significa que todo pasaje sea sencillo: los textos difíciles requieren estudio, comparación y humildad.', references: 'Salmos 119:105,130; 2 Pedro 3:15-16.'),
      StudySection(title: '12. Contexto de interpretación', content: 'Un versículo no debe separarse del párrafo, del libro ni del conjunto bíblico. El contexto permite reconocer quién habla, a quién, en qué situación y con qué propósito.', references: 'Nehemías 8:8; Lucas 24:27; Hechos 8:30-35.'),
      StudySection(title: '13. Estudio diligente', content: 'Creer en la inspiración no autoriza una lectura superficial. El creyente debe estudiar, comparar pasajes y manejar correctamente la palabra de verdad; la diligencia honra el mensaje recibido.', references: '2 Timoteo 2:15; Hechos 17:11.'),
      StudySection(title: '14. Iluminación del Espíritu', content: 'La iluminación es la ayuda del Espíritu Santo para comprender y recibir la verdad revelada. Debe distinguirse de la inspiración: una se relaciona con el lector y la otra con la comunicación original de la Escritura.', references: '1 Corintios 2:12-14; Efesios 1:17-18.'),
      StudySection(title: '15. Revelación e inspiración', content: 'Revelación es el acto por el que Dios da a conocer una verdad; inspiración es su dirección para que el mensaje quede comunicado en la Escritura. Son conceptos relacionados, pero distintos.', references: 'Hebreos 1:1-2; Daniel 2:19-22; 2 Timoteo 3:16.'),
      StudySection(title: '16. Inspiración e iluminación', content: 'No toda impresión o comprensión espiritual constituye nueva Escritura. El Espíritu ayuda a entender la Palabra, pero las opiniones personales no reciben la autoridad de los escritos inspirados.', references: '1 Corintios 2:12-13; 1 Juan 4:1.'),
      StudySection(title: '17. Formación del canon', content: 'El canon es el conjunto de libros reconocidos como Escritura. La Iglesia recibió y reconoció los escritos proféticos y apostólicos; no les concedió inspiración por decisión humana, sino que reconoció su autoridad.', references: 'Lucas 24:44; 1 Timoteo 5:18; 2 Pedro 3:15-16.'),
      StudySection(title: '18. Autoridad apostólica', content: 'Jesús preparó a sus apóstoles para dar testimonio de Él. Los escritos apostólicos tienen un lugar fundamental en el testimonio del nuevo pacto por su vínculo con la enseñanza y comisión de Cristo.', references: 'Juan 14:26; 15:26-27; Efesios 2:19-20.'),
      StudySection(title: '19. Antiguo y Nuevo Testamento', content: 'El Nuevo Testamento no presenta al Antiguo como una revelación inútil. Cristo cumple las promesas y muestra su sentido dentro del propósito divino; ambos testamentos se interpretan en continuidad.', references: 'Mateo 5:17-18; Lucas 24:44-47.'),
      StudySection(title: '20. Jesús y las Escrituras', content: 'Jesús apeló a las Escrituras, respondió a la tentación mediante ellas y corrigió interpretaciones que deformaban su sentido. Su ejemplo enseña a recibir la Palabra con obediencia y no como instrumento de intereses personales.', references: 'Mateo 4:1-11; Juan 10:35.'),
      StudySection(title: '21. El Verbo y el texto escrito', content: 'Jesucristo es el Verbo eterno que revela a Dios; la Biblia es el testimonio escrito inspirado que comunica el propósito divino y conduce a Cristo. No debe confundirse al Hijo personal con los documentos que dan testimonio de Él.', references: 'Juan 1:1-18; Lucas 24:27; Juan 5:39.'),
      StudySection(title: '22. La Trinidad y la comunicación bíblica', content: 'El Padre lleva adelante su propósito revelador, el Hijo es la revelación culminante y el Espíritu actuó en los autores y ayuda a comprender. Estas acciones pertenecen al único Dios y no confunden a las personas divinas.', references: 'Hebreos 1:1-2; Juan 1:18; 2 Pedro 1:21.'),
      StudySection(title: '23. Profecía bíblica', content: 'Los profetas comunicaron mensajes divinos para situaciones concretas y, en ocasiones, anunciaron acontecimientos futuros. La profecía llama a la fidelidad y no debe convertirse en adivinación o especulación.', references: 'Deuteronomio 18:18-22; Jeremías 1:4-10.'),
      StudySection(title: '24. Investigación y testimonios', content: 'Algunos escritores registraron testimonios, documentos y recuerdos transmitidos por testigos. La investigación responsable no contradice la inspiración; muestra que Dios comunicó su verdad mediante trabajo cuidadoso.', references: 'Lucas 1:1-4; Juan 21:24; 1 Juan 1:1-3.'),
      StudySection(title: '25. Manuscritos y transmisión', content: 'Los textos fueron copiados y transmitidos a través de generaciones. Las variantes manuscritas requieren comparación rigurosa; no justifican concluir que el mensaje central dependa de una lectura incierta.', references: 'Jeremías 36:1-4,27-32; Colosenses 4:16.'),
      StudySection(title: '26. Traducciones bíblicas', content: 'La traducción permite que distintos pueblos lean las Escrituras. Toda traducción implica decisiones lingüísticas, por lo que conviene comparar versiones y consultar el contexto para comunicar fielmente el sentido original.', references: 'Nehemías 8:8; Hechos 2:6-11.'),
      StudySection(title: '27. Uso de Reina-Valera 1960', content: 'La RVR1960 es una versión ampliamente utilizada en español y puede servir como texto principal de estudio. Como toda traducción, debe leerse atendiendo a su lenguaje y compararse cuando una expresión resulte difícil.', references: 'Hechos 17:11; 2 Timoteo 2:15.'),
      StudySection(title: '28. Dificultades aparentes', content: 'Algunos pasajes presentan detalles complementarios o dificultades interpretativas. La respuesta responsable no es ocultarlas ni declarar contradicción sin investigar: se comparan relatos, géneros, contextos y propósitos.', references: 'Proverbios 18:13; Lucas 1:1-4; 2 Pedro 3:16.'),
      StudySection(title: '29. Unidad del mensaje', content: 'La Biblia fue escrita por diversos autores y en distintos periodos, pero desarrolla el propósito coherente de Dios. Unidad no significa uniformidad literaria; las voces particulares se integran en la historia redentora.', references: 'Lucas 24:27,44; Efesios 1:9-10.'),
      StudySection(title: '30. Norma para evaluar doctrinas', content: 'Toda enseñanza debe examinarse, no aceptarse solo por autoridad, carisma o popularidad. La Iglesia está llamada a probar los mensajes y retener lo bueno conforme al testimonio bíblico.', references: 'Hechos 17:11; 1 Tesalonicenses 5:20-21.'),
      StudySection(title: '31. Tradición y Escritura', content: 'La historia de la Iglesia aporta información valiosa, pero debe evaluarse a la luz de la Palabra. Jesús denunció tradiciones humanas que anulaban el mandamiento divino; la tradición sirve a la verdad, no la sustituye.', references: 'Marcos 7:6-13; Colosenses 2:8.'),
      StudySection(title: '32. La Escritura en la predicación', content: 'La predicación debe exponer el mensaje bíblico y no usar versículos como adornos de ideas personales. Quien predica anuncia una verdad que no le pertenece y debe comunicarla con fidelidad.', references: '2 Timoteo 4:1-2; Tito 2:1.'),
      StudySection(title: '33. Enseñanza en la Iglesia', content: 'La comunidad debe formar a sus miembros mediante enseñanza constante. La instrucción incluye explicación, corrección y preparación para toda buena obra; busca madurez en Cristo, no mera acumulación de datos.', references: 'Colosenses 3:16; Efesios 4:11-14.'),
      StudySection(title: '34. Formación en el hogar', content: 'La Palabra debe ocupar un lugar en la formación familiar. Enseñar a niños y jóvenes requiere constancia, ejemplo y explicaciones adecuadas; la fe se comunica con instrucción y amor responsable.', references: 'Deuteronomio 6:6-9; Efesios 6:4.'),
      StudySection(title: '35. Transformación del carácter', content: 'La Palabra confronta pensamientos, intenciones y conductas. Su propósito no es alimentar orgullo intelectual, sino conducir a una vida que agrade a Dios y se exprese en obediencia y misericordia.', references: 'Hebreos 4:12; Santiago 1:22-25.'),
      StudySection(title: '36. Discernimiento espiritual', content: 'El discernimiento requiere conocer la verdad y examinar lo que se presenta como mensaje espiritual. No toda impresión o sueño atribuido a Dios posee autoridad divina; el Espíritu no contradice la Palabra inspirada.', references: '1 Juan 4:1-3; 1 Tesalonicenses 5:19-22.'),
      StudySection(title: '37. Falsos maestros', content: 'La Biblia advierte que algunos distorsionan la verdad para obtener seguidores o beneficios. La respuesta combina conocimiento doctrinal, vigilancia, carácter íntegro y corrección apostólica.', references: 'Mateo 7:15-20; Hechos 20:28-30.'),
      StudySection(title: '38. Libertad cristiana', content: 'La Palabra orienta la conciencia y distingue mandamientos divinos de reglas humanas. No debe utilizarse para imponer cargas que Dios no ordenó ni para justificar irresponsabilidad; la libertad permanece sometida al amor.', references: 'Gálatas 5:1,13-14; Colosenses 2:16-23.'),
      StudySection(title: '39. Justicia y Palabra', content: 'La autoridad bíblica se expresa en el llamado a practicar justicia y defender al vulnerable. No se deben utilizar textos religiosos para encubrir abuso, corrupción o favoritismo; la interpretación fiel respeta el carácter justo de Dios.', references: 'Miqueas 6:8; Isaías 1:16-17; Santiago 2:1-9.'),
      StudySection(title: '40. Consuelo en la aflicción', content: 'Las promesas bíblicas sostienen a quienes atraviesan pruebas. El consuelo no niega el dolor ni promete que todo problema desaparecerá inmediatamente; recuerda la fidelidad de Dios y orienta a perseverar.', references: 'Salmos 119:50; Romanos 15:4; 2 Corintios 1:3-4.'),
      StudySection(title: '41. Esperanza cristiana', content: 'La Biblia anuncia el propósito redentor de Dios y la esperanza en Jesucristo. Esta esperanza descansa en promesas reveladas, no en interpretaciones sensacionalistas, y llama a vivir con sobriedad y fidelidad.', references: 'Tito 2:11-13; 1 Pedro 1:3-5.'),
      StudySection(title: '42. Fe y obediencia', content: 'Escuchar la Palabra sin responder conduce al autoengaño. La fe recibe el mensaje y la obediencia muestra que ha sido tomado en serio; las obras no compran la gracia, sino que expresan confianza genuina.', references: 'Santiago 1:22-25; Hebreos 4:2; Juan 14:23.'),
      StudySection(title: '43. Oración y lectura', content: 'La lectura bíblica y la oración se complementan. La Palabra orienta nuestras peticiones y corrige deseos; la oración expresa dependencia de Dios. Ninguna debe usarse como excusa para abandonar la otra.', references: 'Juan 15:7; Salmos 119:18; Colosenses 4:2.'),
      StudySection(title: '44. Misión de la Iglesia', content: 'La Iglesia anuncia el evangelio recibido y transmite la enseñanza de Cristo a las naciones. La misión no autoriza a modificar el mensaje por conveniencia; exige fidelidad, amor, claridad y respeto.', references: 'Mateo 28:18-20; Lucas 24:46-49.'),
      StudySection(title: '45. Responsabilidad de los maestros', content: 'Quienes enseñan tienen responsabilidad especial. Deben estudiar, explicar correctamente, evitar afirmaciones infundadas y reconocer los límites de su conocimiento; la autoridad espiritual no permite manipular.', references: 'Santiago 3:1; 2 Timoteo 2:15; 1 Pedro 5:2-3.'),
      StudySection(title: '46. Crecimiento continuo', content: 'El creyente debe crecer en el conocimiento de la Palabra durante toda su vida. Ninguna etapa permite considerarse por encima de la corrección bíblica; la madurez requiere constancia y humildad.', references: '2 Pedro 3:18; Colosenses 1:9-10.'),
      StudySection(title: '47. Permanencia de la Palabra', content: 'La Escritura presenta la Palabra de Dios como firme y duradera. Los poderes humanos y los cambios culturales no invalidan la fidelidad divina; la Iglesia debe conservar el mensaje sin modificarlo por conveniencia.', references: 'Isaías 40:8; Mateo 24:35; 1 Pedro 1:24-25.'),
      StudySection(title: '48. Cristo como centro', content: 'Las Escrituras conducen a comprender la persona y obra de Jesucristo. El Antiguo Testamento prepara la promesa y el Nuevo anuncia su cumplimiento. Reconocer este centro no autoriza a convertir cada pasaje en alegoría arbitraria.', references: 'Lucas 24:25-27; Juan 5:39; Hechos 10:43.'),
      StudySection(title: '49. Fidelidad de la Iglesia', content: 'La Iglesia está llamada a conservar, enseñar y practicar la verdad recibida. Esto exige rechazar la manipulación de los textos y el desprecio por su autoridad; la fidelidad produce una comunidad humilde y justa.', references: '1 Timoteo 3:15; Judas 3; Apocalipsis 22:18-19.'),
      StudySection(title: '50. Lectura comunitaria', content: 'La Escritura forma también al pueblo reunido. Leerla y explicarla en comunidad permite corregir interpretaciones aisladas, aprender unos de otros y fortalecer la unidad; esto complementa, no reemplaza, el estudio personal.', references: 'Colosenses 3:16; 1 Timoteo 4:13; Hechos 2:42.'),
    ],
    conclusion: '''La inspiración de las Escrituras enseña que la Biblia procede de Dios y fue comunicada mediante autores humanos bajo la obra del Espíritu Santo. Su diversidad literaria e histórica no elimina la unidad de su mensaje ni su autoridad para la fe y la vida cristiana. La Iglesia debe leerla en contexto, reconocer sus géneros, comparar pasajes y distinguir el texto inspirado de las interpretaciones humanas.

Jesucristo es la revelación culminante del Padre y el centro del testimonio bíblico; el Espíritu Santo actuó en la comunicación de la Palabra y ayuda a comprenderla, sin conducir a enseñanzas contrarias a ella. Recibir la Biblia exige fe, discernimiento, obediencia, justicia y amor. La comunidad honra a Dios cuando conserva el mensaje recibido, lo enseña con fidelidad y permite que transforme su conducta.''',
  ),
Study(
    number: '84',
    title: "La evangelización cristiana: el anuncio del evangelio, el llamado al arrepentimiento y el testimonio de la Iglesia",
    subtitle: 'El mandato de anunciar a Jesucristo, llamar a la fe y formar discípulos con fidelidad y compasión.',
    introduction: "La evangelización es el anuncio de las buenas noticias de Dios acerca de Jesucristo. La Iglesia proclama que el Hijo vino, murió por los pecados, resucitó y reina; por medio de Él se ofrece reconciliación con Dios y se llama a todas las personas al arrepentimiento y a la fe.\n\nLa misión cristiana no consiste en imponer una cultura, manipular emociones, prometer prosperidad ni aumentar cifras institucionales. Consiste en comunicar fielmente el evangelio, vivir de manera coherente con él, escuchar con respeto y acompañar a quienes comienzan a seguir a Cristo. La proclamación debe estar unida al discipulado, la comunión de la Iglesia y el servicio al prójimo.\n\nEste estudio examina el fundamento bíblico de la evangelización, su contenido, sus formas de comunicación, la obra del Dios trino, la responsabilidad del mensajero y el alcance mundial de la misión.",
    sections: [
      StudySection(title: "1. El significado bíblico de evangelizar", content: "Evangelizar es anunciar buenas noticias. En el Nuevo Testamento el centro del anuncio es Jesucristo: su identidad, su muerte, su resurrección y el llamado a responder con fe.", references: "Marcos 1:14-15; 1 Corintios 15:1-4"),
      StudySection(title: "2. El reino de Dios como contenido del anuncio", content: "Jesús anunció que el reino de Dios se había acercado. La Iglesia proclama el gobierno salvador de Dios inaugurado en Cristo y espera su manifestación plena.", references: "Marcos 1:14-15; Lucas 8:1"),
      StudySection(title: "3. Jesucristo como centro del mensaje", content: "La proclamación cristiana no puede separarse de la persona y obra del Hijo. Un mensaje de espiritualidad que omite a Cristo no comunica el evangelio apostólico en su centro.", references: "Hechos 4:10-12; 1 Corintios 2:1-2"),
      StudySection(title: "4. La cruz en la proclamación", content: "La muerte de Cristo no es un detalle secundario: es el sacrificio redentor anunciado por los apóstoles. La evangelización explica su significado sin convertirlo en una fórmula vacía.", references: "1 Corintios 1:18-24; 1 Pedro 2:24"),
      StudySection(title: "5. La resurrección como fundamento de esperanza", content: "El anuncio apostólico afirma que Jesús resucitó. La resurrección confirma la victoria de Cristo y sostiene la esperanza y la fe de la Iglesia.", references: "1 Corintios 15:3-8,17-20; Hechos 2:24"),
      StudySection(title: "6. La realidad del pecado", content: "El evangelio explica por qué necesitamos reconciliación con Dios: todos han pecado y no pueden justificarse por sus propios méritos. Esta verdad debe comunicarse sin humillar ni manipular.", references: "Romanos 3:9-23; Efesios 2:1-5"),
      StudySection(title: "7. El llamado al arrepentimiento", content: "Arrepentirse implica reconocer el pecado y volverse a Dios. No es solo remordimiento ni una promesa de perfección inmediata, sino una respuesta sincera que produce frutos coherentes.", references: "Marcos 1:15; Hechos 3:19; 2 Corintios 7:10"),
      StudySection(title: "8. La fe en Jesucristo", content: "La respuesta al evangelio incluye confiar en la persona y obra de Cristo. La fe no es mera aceptación intelectual, sino confianza que recibe la promesa de Dios y conduce al seguimiento.", references: "Juan 3:16-18; Hechos 16:30-31"),
      StudySection(title: "9. La salvación como regalo de gracia", content: "La salvación no se compra con obras, donaciones ni adhesión institucional. La Iglesia debe anunciar que Dios salva por gracia y que las buenas obras son fruto, no precio, de esa salvación.", references: "Efesios 2:8-10; Tito 3:4-7"),
      StudySection(title: "10. La invitación a todas las personas", content: "El mensaje debe anunciarse sin discriminación por origen, condición económica o pasado. La invitación del evangelio alcanza a personas de todas las naciones.", references: "Mateo 28:18-20; Hechos 17:30-31"),
      StudySection(title: "11. La comisión de Jesucristo", content: "Jesús envió a sus discípulos a hacer discípulos de todas las naciones. La misión incluye proclamar, bautizar y enseñar a obedecer lo que Él mandó.", references: "Mateo 28:18-20; Juan 20:21"),
      StudySection(title: "12. El poder del Espíritu Santo para testificar", content: "El Espíritu capacita a los creyentes para dar testimonio de Cristo. La misión requiere valentía y dependencia de Dios, sin usar la espiritualidad como excusa para la pasividad.", references: "Juan 15:26-27; Hechos 1:8"),
      StudySection(title: "13. El propósito del Padre en la misión", content: "El Padre envió al Hijo por amor y llama a las personas a la vida en Cristo. La misión nace de la iniciativa salvadora de Dios, no de la ambición de una organización.", references: "Juan 3:16-17; Juan 6:44"),
      StudySection(title: "14. La obra misionera del Hijo", content: "Jesús vino a buscar y salvar lo que se había perdido y entregó su vida en rescate. La Iglesia anuncia su obra suficiente y su autoridad, sin sustituirlo por líderes humanos.", references: "Marcos 10:45; Lucas 19:10"),
      StudySection(title: "15. La obra trinitaria en la evangelización", content: "El Padre envía, el Hijo realiza la redención y comisiona a sus discípulos, y el Espíritu capacita el testimonio. Es la obra armoniosa del único Dios en la salvación.", references: "Mateo 28:19-20; Hechos 1:8; 1 Pedro 1:2"),
      StudySection(title: "16. El modelo de la predicación apostólica", content: "Los apóstoles anunciaron a Jesús desde las Escrituras, explicaron su muerte y resurrección y llamaron a responder. Su ejemplo une fidelidad al mensaje y atención a la audiencia.", references: "Hechos 2:14-41; Hechos 13:16-41"),
      StudySection(title: "17. La conversación evangelística personal", content: "El encuentro personal permite escuchar preguntas y explicar el evangelio con claridad. Como Felipe con el funcionario etíope, el creyente puede partir de las inquietudes reales de quien escucha.", references: "Hechos 8:26-35; Colosenses 4:5-6"),
      StudySection(title: "18. La proclamación en espacios públicos", content: "La proclamación pública permite comunicar el mensaje a muchas personas. Debe realizarse con respeto, claridad y prudencia, sin intimidación ni interrupciones abusivas.", references: "Hechos 2:14-36; Hechos 17:16-17"),
      StudySection(title: "19. El testimonio dentro de la familia", content: "Compartir la fe en el hogar requiere paciencia, coherencia y amor. La enseñanza cotidiana puede hablar de Dios, pero nadie debe ser controlado o amenazado para producir una respuesta religiosa.", references: "Deuteronomio 6:6-9; Marcos 5:19"),
      StudySection(title: "20. La misión entre culturas y pueblos", content: "El evangelio se dirige a todas las naciones. El mensajero debe escuchar y comprender el contexto, evitando confundir costumbres propias con requisitos bíblicos.", references: "Hechos 10:34-35; 1 Corintios 9:19-23"),
      StudySection(title: "21. La claridad para distintas audiencias", content: "La comunicación debe explicar términos y evitar lenguaje innecesariamente técnico. Adaptar la forma de hablar ayuda a comprender, pero no autoriza a cambiar el contenido del evangelio.", references: "Hechos 17:22-23; 1 Corintios 14:8-9"),
      StudySection(title: "22. La compasión por quienes escuchan", content: "Las personas no son cifras ni objetivos. La compasión de Jesús enseña a escuchar, respetar la dignidad humana y comunicar la verdad sin desprecio.", references: "Mateo 9:35-38; Marcos 6:34"),
      StudySection(title: "23. La coherencia de la conducta cristiana", content: "La conducta puede confirmar o desacreditar el anuncio. La integridad y el amor no reemplazan la predicación, pero muestran el fruto de una vida transformada por Cristo.", references: "Mateo 5:14-16; 1 Pedro 2:12"),
      StudySection(title: "24. La defensa razonada de la esperanza", content: "El creyente puede explicar las razones de su esperanza con mansedumbre. La apologética sirve al testimonio, pero no debe convertirse en competencia para humillar.", references: "Hechos 17:16-34; 1 Pedro 3:15-16"),
      StudySection(title: "25. La escucha de objeciones y preguntas", content: "Las preguntas deben escucharse antes de responder. Algunas nacen de dudas intelectuales y otras de experiencias dolorosas; una respuesta fiel reconoce límites y evita caricaturizar al interlocutor.", references: "Proverbios 18:13; Colosenses 4:6"),
      StudySection(title: "26. La verdad y la honestidad del mensaje", content: "No se deben prometer riqueza, ausencia de problemas ni resultados que Dios no ha garantizado. El evangelio debe comunicarse sin engaño, exageración ni manipulación.", references: "2 Corintios 4:1-2; 1 Tesalonicenses 2:3-5"),
      StudySection(title: "27. La libertad de quien escucha", content: "La Iglesia presenta la verdad y llama a responder, pero no debe manipular mediante amenazas humanas o presión emocional. La respuesta debe ser responsable delante de Dios.", references: "Hechos 17:32-34; Filemón 8-9"),
      StudySection(title: "28. La paciencia en la evangelización", content: "No todos comprenden ni responden al mismo tiempo. El creyente anuncia y persevera, dejando a Dios el crecimiento y evitando controlar los resultados.", references: "Marcos 4:26-29; 1 Corintios 3:5-7"),
      StudySection(title: "29. La oración por oportunidades y valentía", content: "La Iglesia ora para que Dios abra puertas y dé valor para hablar claramente. La oración sostiene la misión y reconoce la dependencia de la gracia divina.", references: "Colosenses 4:2-4; Efesios 6:18-20"),
      StudySection(title: "30. La preparación de quienes anuncian", content: "La formación incluye conocimiento bíblico, carácter, capacidad de escuchar y disposición para servir. No basta dominar técnicas de persuasión; el mensajero debe comprender el evangelio.", references: "2 Timoteo 2:2; Tito 2:1-8"),
      StudySection(title: "31. El discipulado después de recibir el mensaje", content: "La misión no termina con una profesión inicial de fe. Jesús mandó formar discípulos que aprendan a obedecer; el acompañamiento ayuda a crecer y perseverar.", references: "Mateo 28:19-20; Colosenses 1:28"),
      StudySection(title: "32. La comunión de la iglesia local", content: "La fe cristiana no está diseñada como aislamiento. Los nuevos creyentes necesitan enseñanza, comunión, oración y servicio dentro de una comunidad responsable.", references: "Hechos 2:41-47; Hebreos 10:24-25"),
      StudySection(title: "33. El bautismo como confesión pública", content: "El bautismo acompaña la incorporación del discípulo a la comunidad cristiana y expresa su identificación con Cristo. No debe sustituir la fe ni utilizarse como herramienta de presión.", references: "Mateo 28:19; Romanos 6:3-4"),
      StudySection(title: "34. La misericordia como expresión de la misión", content: "La Iglesia anuncia y sirve al prójimo. Las obras de misericordia no compran salvación ni reemplazan el evangelio, pero expresan el amor recibido en Cristo.", references: "Mateo 5:16; Gálatas 6:9-10"),
      StudySection(title: "35. La justicia como parte del testimonio", content: "No se puede anunciar reconciliación mientras se tolera deliberadamente la explotación y la corrupción. La vida cristiana debe reflejar justicia y cuidado del prójimo.", references: "Miqueas 6:8; Santiago 2:1-9"),
      StudySection(title: "36. La evangelización sin favoritismo", content: "El evangelio no autoriza despreciar por procedencia, riqueza o pasado. La Iglesia debe anunciar con igual dignidad a todas las personas.", references: "Hechos 10:34-35; Santiago 2:1-4"),
      StudySection(title: "37. La protección de personas vulnerables", content: "La actividad evangelística debe proteger la dignidad y seguridad de quienes participan. Nunca debe utilizarse la religión para obtener favores, dinero, silencio o acceso indebido.", references: "Mateo 18:5-6; 1 Tesalonicenses 2:7-8"),
      StudySection(title: "38. La integridad económica de la misión", content: "El evangelio no es un negocio. El apoyo legítimo a quienes sirven requiere transparencia y nunca debe manipularse la fe para enriquecerse o vender bendiciones.", references: "Mateo 10:8; Hechos 20:33-35; 2 Corintios 8:20-21"),
      StudySection(title: "39. La cooperación entre congregaciones", content: "La cooperación misionera requiere respeto, verdad y acuerdos claros. Las diferencias secundarias no deben destruir el trabajo común, pero tampoco se deben ocultar desacuerdos esenciales.", references: "Juan 17:20-23; Filipenses 1:15-18"),
      StudySection(title: "40. La oposición y la respuesta cristiana", content: "La oposición no justifica violencia ni venganza. Los creyentes perseveran, hablan con mansedumbre y actúan con prudencia, aun cuando no todos acepten el mensaje.", references: "Mateo 5:11-12; 1 Pedro 3:14-16"),
      StudySection(title: "41. La prudencia del mensajero", content: "El celo debe acompañarse de sabiduría. Hay momentos para hablar, escuchar, retirarse o buscar ayuda; la prudencia protege al mensajero y a quienes reciben el mensaje.", references: "Mateo 10:16,23; Colosenses 4:5-6"),
      StudySection(title: "42. La contextualización sin cambiar el evangelio", content: "Pablo adaptó su acercamiento a distintas audiencias sin abandonar la fidelidad a Cristo. La contextualización cambia formas de comunicación, no el contenido esencial de la cruz y la resurrección.", references: "1 Corintios 9:19-23; Gálatas 1:8-9"),
      StudySection(title: "43. El discernimiento ante falsos evangelios", content: "Deben rechazarse mensajes que sustituyen a Cristo por prosperidad garantizada, méritos humanos o líderes incuestionables. El evangelio apostólico no puede modificarse para ganar popularidad.", references: "Gálatas 1:6-9; Colosenses 2:8"),
      StudySection(title: "44. La esperanza en medio del sufrimiento", content: "El evangelio ofrece esperanza, pero no promete que toda dificultad desaparecerá de inmediato. El mensajero debe escuchar con compasión y anunciar con honestidad la esperanza en Cristo.", references: "Romanos 8:18-25; 2 Corintios 1:3-7"),
      StudySection(title: "45. La perseverancia sin medir solo cifras", content: "La fidelidad no se mide únicamente por resultados visibles. El creyente anuncia y sirve, confiando en Dios y evitando la competencia, la manipulación y el desaliento.", references: "Isaías 55:10-11; Gálatas 6:9"),
      StudySection(title: "46. La responsabilidad misionera de la congregación", content: "La misión pertenece a toda la comunidad mediante oración, formación, hospitalidad, servicio y proclamación. No es tarea exclusiva de una persona ni un evento aislado.", references: "Hechos 13:1-3; 1 Pedro 2:9"),
      StudySection(title: "47. El alcance mundial del evangelio", content: "La Iglesia debe mantener una visión que supere su localidad y apoyar la proclamación entre los pueblos. La diversidad de naciones forma parte del propósito redentor de Dios.", references: "Mateo 24:14; Apocalipsis 7:9-10"),
      StudySection(title: "48. La esperanza de la consumación de la misión", content: "La misión continuará hasta el cumplimiento del propósito de Dios. La esperanza futura impulsa la fidelidad presente y recuerda que la historia está bajo el señorío de Cristo.", references: "Mateo 24:14; Apocalipsis 5:9-10"),
      StudySection(title: "49. La evangelización como amor al prójimo", content: "Anunciar a Cristo comparte la noticia de la reconciliación. El amor no obliga ni manipula: busca el bien del otro y comunica la verdad con paciencia.", references: "Mateo 22:37-39; Romanos 10:13-15"),
      StudySection(title: "50. El testimonio cotidiano de cada creyente", content: "Cada cristiano puede dar razón de su esperanza según sus capacidades y oportunidades. Todos están llamados a vivir con coherencia y hablar con verdad cuando corresponda.", references: "1 Pedro 3:15-16; Colosenses 4:6"),
    ],
    conclusion: "La evangelización cristiana anuncia a Jesucristo crucificado y resucitado, llama al arrepentimiento y a la fe, y conduce a formar discípulos que aprenden a obedecer al Señor. Su fundamento está en la autoridad de Cristo y en la obra del único Dios: el Padre envía y llama, el Hijo realiza la redención y comisiona a su Iglesia, y el Espíritu Santo capacita el testimonio.\n\nLa fidelidad evangelística exige comunicar el mensaje completo sin manipulación, discriminación, engaño ni intereses económicos. También demanda escuchar, responder con mansedumbre, proteger a las personas vulnerables, servir al prójimo y acompañar a quienes reciben el evangelio.\n\nLa Iglesia debe perseverar en la misión, formar a sus miembros, colaborar con prudencia y mirar hacia todas las naciones, confiando en que Dios da el crecimiento. El propósito final no es la fama del mensajero ni el prestigio de una institución, sino que las personas conozcan a Jesucristo y glorifiquen a Dios.",
  ),
Study(
    number: '85',
    title: "El discipulado cristiano: seguir, aprender y obedecer a Jesucristo",
    subtitle: 'La formación integral de quienes responden al llamado de Jesús y viven bajo su señorío.',
    introduction: "La evangelización anuncia las buenas noticias de Jesucristo y llama a responder con arrepentimiento y fe; el discipulado desarrolla esa respuesta en una vida de seguimiento, aprendizaje y obediencia. Ser discípulo no consiste únicamente en asistir a reuniones, acumular información o adoptar una identidad religiosa. Significa pertenecer a Cristo, escuchar su Palabra, imitar su ejemplo y crecer en comunión con Dios y con su Iglesia.\n\nEste estudio aborda el fundamento bíblico del discipulado, la gracia que lo sostiene, el llamado de Jesús, la obra del Padre, del Hijo y del Espíritu Santo, la formación del carácter, las disciplinas espirituales, las relaciones, el servicio, la perseverancia y la misión. También distingue el acompañamiento cristiano del control abusivo y la obediencia bíblica del legalismo. Su propósito es comprender cómo una persona que ha recibido el evangelio aprende a vivir cada día como discípulo de Jesucristo.",
    sections: [
      StudySection(title: "1. El significado de ser discípulo", content: "Un discípulo aprende de Jesús, confía en Él y ordena su vida bajo su enseñanza. No consiste solo en asistir a reuniones o conocer información religiosa: implica seguir al Señor y permitir que su verdad transforme decisiones y conducta.", references: "Mt 4:19; Lc 6:40"),
      StudySection(title: "2. El llamado personal de Jesús", content: "Jesús llamó a personas concretas a seguirlo. Su invitación demanda una respuesta consciente: escuchar su voz, reconocer su autoridad y comenzar a caminar bajo su dirección.", references: "Mr 1:16-20; Jn 1:43"),
      StudySection(title: "3. Cristo como Señor y Maestro", content: "El discipulado tiene a Jesucristo como autoridad suprema. Sus enseñanzas no son consejos opcionales para admiradores, sino la dirección del Señor para quienes dicen pertenecerle.", references: "Jn 13:13-15; Lc 6:46"),
      StudySection(title: "4. La gracia como fundamento del seguimiento", content: "Nadie se convierte en discípulo para comprar la salvación. El seguimiento responde a la gracia recibida; la obediencia es fruto de la fe, no el precio de la aceptación divina.", references: "Ef 2:8-10; Tit 2:11-14"),
      StudySection(title: "5. Arrepentimiento y vida nueva", content: "Seguir a Cristo incluye volverse de los caminos contrarios a Dios. El arrepentimiento no es solo tristeza, sino un cambio de dirección que reconoce el pecado y busca vivir conforme a la voluntad del Señor.", references: "Mr 1:15; Hch 3:19"),
      StudySection(title: "6. La fe que persevera", content: "La fe recibe a Cristo y continúa confiando en Él. No significa ausencia de preguntas o dificultades, sino dependencia perseverante de la fidelidad de Dios y de la obra suficiente del Salvador.", references: "Col 2:6-7; Heb 10:38-39"),
      StudySection(title: "7. Negarse a sí mismo", content: "Jesús enseñó que el discípulo no debe colocar sus deseos por encima de la voluntad de Dios. Negarse a sí mismo significa renunciar al egoísmo y someter las decisiones al señorío de Cristo.", references: "Lc 9:23-24; Gá 2:20"),
      StudySection(title: "8. Tomar la cruz y seguir a Jesús", content: "Tomar la cruz expresa la disposición a permanecer fiel a Cristo aun cuando el seguimiento tenga un costo. No es buscar sufrimiento, sino no abandonar la obediencia por temor a la oposición.", references: "Mt 16:24-26; 1 P 2:21"),
      StudySection(title: "9. Contar el costo del discipulado", content: "Jesús llamó a considerar seriamente lo que implica seguirlo. El entusiasmo inicial debe convertirse en compromiso reflexivo, sin prometer una vida libre de dificultades ni exigir decisiones impulsivas.", references: "Lc 14:25-33; Jn 15:18-20"),
      StudySection(title: "10. Amar a Dios sobre todas las cosas", content: "El primer mandamiento orienta todo el discipulado: Dios debe ocupar el lugar supremo en el corazón y las prioridades. Ese amor se expresa en fidelidad y obediencia, no solamente en palabras.", references: "Mt 22:37-38; Dt 6:4-6"),
      StudySection(title: "11. Amar al prójimo como Cristo enseñó", content: "El seguimiento se evidencia en el trato hacia otras personas. El discípulo busca el bien del prójimo, rechaza el favoritismo y practica un amor que actúa con justicia y misericordia.", references: "Mt 22:39; Jn 13:34-35"),
      StudySection(title: "12. Permanecer en la Palabra de Cristo", content: "Permanecer en la Palabra implica estudiar la enseñanza de Jesús en contexto, creerla y permitir que corrija pensamientos y prácticas. El discípulo necesita escucharla de manera constante.", references: "Jn 8:31-32; Col 3:16"),
      StudySection(title: "13. Aprender a obedecer", content: "La obediencia es una respuesta concreta al señorío de Cristo. No basta admirar sus enseñanzas; el discípulo procura ponerlas en práctica en la familia, la congregación y la vida cotidiana.", references: "Mt 7:24-27; Jn 14:21"),
      StudySection(title: "14. La oración en la vida del discípulo", content: "Jesús enseñó a orar con confianza, reverencia y dependencia del Padre. La oración no controla a Dios; expresa comunión, petición, gratitud y sometimiento a su voluntad.", references: "Mt 6:5-13; Lc 11:1-4"),
      StudySection(title: "15. La comunión con el Padre por medio del Hijo", content: "El discípulo se acerca al Padre por medio de Jesucristo. La oración cristiana reconoce la mediación del Hijo y la relación filial que Dios concede a quienes creen.", references: "Jn 14:6; Ef 2:18"),
      StudySection(title: "16. La obra del Espíritu Santo en el crecimiento", content: "El Espíritu Santo obra en el creyente, produciendo transformación y capacitando para obedecer. El crecimiento espiritual no es autosuperación independiente, sino fruto de la gracia y de la obra divina.", references: "Ro 8:9-14; Gá 5:16-25"),
      StudySection(title: "17. El discipulado y la Trinidad", content: "La vida del discípulo se desarrolla en la obra del único Dios: el Padre llama y adopta, el Hijo redime y enseña, y el Espíritu regenera, habita y transforma. Las personas divinas actúan en perfecta unidad.", references: "Mt 28:19; Ef 1:3-14; 1 P 1:2"),
      StudySection(title: "18. La formación del carácter cristiano", content: "El aprendizaje de Cristo produce humildad, paciencia, dominio propio, bondad y fidelidad. El carácter no se forma por apariencia religiosa, sino mediante la verdad y la dependencia del Espíritu.", references: "Col 3:12-17; Gá 5:22-23"),
      StudySection(title: "19. La santidad como fruto del seguimiento", content: "El discípulo es llamado a apartarse del pecado y vivir para Dios. La santidad no es superioridad sobre otras personas, sino una vida consagrada que refleja el carácter del Señor.", references: "1 P 1:14-16; 1 Ts 4:3-7"),
      StudySection(title: "20. La renovación de la mente", content: "La Palabra transforma la manera de pensar para discernir la voluntad de Dios. El discípulo examina ideas, costumbres y deseos a la luz de la verdad.", references: "Ro 12:1-2; Ef 4:20-24"),
      StudySection(title: "21. La humildad para aprender y corregirse", content: "Ningún discípulo alcanza conocimiento completo en esta vida. La humildad permite recibir enseñanza, reconocer errores y corregirse sin convertir la crítica en rivalidad.", references: "Pr 9:9; Stg 4:6; 1 P 5:5"),
      StudySection(title: "22. La disciplina espiritual sin legalismo", content: "La lectura bíblica, la oración, la congregación y el servicio ayudan al crecimiento. Son medios de formación, no mecanismos para ganar el amor de Dios ni motivos para juzgar a otros.", references: "1 Ti 4:7-8; Heb 10:24-25"),
      StudySection(title: "23. El ejemplo de Jesús en el servicio", content: "Jesús mostró que la grandeza en su reino se expresa sirviendo. El discípulo no utiliza cargos para dominar, sino que procura el bien de otros con responsabilidad.", references: "Mr 10:42-45; Jn 13:12-17"),
      StudySection(title: "24. El servicio según los dones recibidos", content: "Cada creyente puede contribuir a la edificación de la comunidad conforme a las capacidades recibidas. El servicio no es competencia por reconocimiento, sino colaboración para el bien común.", references: "Ro 12:4-8; 1 P 4:10-11"),
      StudySection(title: "25. La vida del discípulo en la iglesia local", content: "El crecimiento cristiano ocurre en comunión con otros creyentes. La congregación ofrece enseñanza, acompañamiento, corrección, adoración y oportunidades para servir.", references: "Hch 2:42-47; Ef 4:11-16"),
      StudySection(title: "26. La responsabilidad de enseñar a otros", content: "Quien aprende de Cristo también transmite fielmente la enseñanza recibida. Formar nuevos discípulos requiere paciencia, ejemplo y fidelidad a la Escritura.", references: "Mt 28:19-20; 2 Ti 2:2"),
      StudySection(title: "27. El discipulado en el hogar", content: "La fe se expresa en relaciones familiares marcadas por respeto, cuidado, verdad y servicio. La enseñanza en el hogar se comunica con palabras y ejemplo, sin autoritarismo.", references: "Dt 6:6-9; Ef 5:21; 6:1-4"),
      StudySection(title: "28. El testimonio en el trabajo y la sociedad", content: "El discípulo honra a Cristo mediante honestidad, responsabilidad y justicia en sus actividades. La conducta diaria puede dar credibilidad al evangelio y debe evitar la hipocresía.", references: "Col 3:17,23-24; 1 Ts 4:11-12"),
      StudySection(title: "29. La administración del tiempo y las prioridades", content: "Seguir a Cristo implica revisar cómo se utilizan el tiempo y las capacidades. El discípulo ordena sus responsabilidades sin descuidar la familia ni su relación con Dios.", references: "Ef 5:15-17; Sal 90:12"),
      StudySection(title: "30. El uso responsable de los recursos", content: "Los bienes materiales deben administrarse con gratitud, generosidad y justicia. El discípulo evita que el dinero gobierne su corazón y aprende a compartir sin buscar reconocimiento.", references: "Mt 6:19-24; 1 Ti 6:17-19"),
      StudySection(title: "31. El cuidado del cuerpo y la vida", content: "La vida humana es don de Dios y debe tratarse con responsabilidad. El discípulo procura decisiones prudentes que honren al Señor en su manera de vivir.", references: "1 Co 6:19-20; Ro 12:1"),
      StudySection(title: "32. La verdad y la integridad del habla", content: "El discípulo rechaza la mentira, el chisme y la manipulación. Sus palabras deben ser confiables, oportunas y edificantes, reflejando la verdad recibida de Cristo.", references: "Ef 4:25,29; Stg 3:1-12"),
      StudySection(title: "33. El perdón y la reconciliación", content: "Quien ha recibido misericordia aprende a perdonar y buscar la paz cuando es posible. Perdonar no significa aprobar el mal ni ignorar la justicia, sino renunciar a la venganza.", references: "Mt 6:14-15; Ef 4:31-32; Ro 12:18-21"),
      StudySection(title: "34. La corrección fraterna con amor", content: "La comunidad cristiana corrige con mansedumbre y propósito restaurador. La corrección no autoriza humillación, control abusivo ni condenas precipitadas; requiere verdad y cuidado.", references: "Mt 18:15-17; Gá 6:1-2"),
      StudySection(title: "35. La sabiduría para escoger amistades", content: "Las relaciones influyen en convicciones y decisiones. El discípulo busca amistades que favorezcan la verdad y procura ser también una influencia respetuosa y constructiva.", references: "Pr 13:20; 1 Co 15:33"),
      StudySection(title: "36. La libertad cristiana y la conciencia", content: "La libertad en Cristo no es permiso para pecar ni despreciar la conciencia ajena. El discípulo usa su libertad para amar y edificar, distinguiendo mandamientos bíblicos de preferencias personales.", references: "Gá 5:13; Ro 14:13-19"),
      StudySection(title: "37. La resistencia ante la tentación", content: "El discípulo reconoce sus debilidades y busca la ayuda de Dios para no ceder al pecado. La vigilancia, la oración y decisiones prudentes forman parte de una vida dependiente del Señor.", references: "Mt 26:41; 1 Co 10:12-13"),
      StudySection(title: "38. El manejo bíblico de las pruebas", content: "Las dificultades pueden probar la fe y formar perseverancia. El discípulo no interpreta todo sufrimiento como castigo personal ni niega el dolor; busca a Dios y recibe apoyo.", references: "Stg 1:2-4; Ro 5:3-5"),
      StudySection(title: "39. La perseverancia ante el desánimo", content: "El cansancio espiritual debe afrontarse con oración, acompañamiento y renovación en la verdad. Perseverar no significa ocultar las luchas, sino buscar ayuda y continuar confiando en Dios.", references: "Gá 6:9; Heb 12:1-3"),
      StudySection(title: "40. La fidelidad en medio de la oposición", content: "Seguir a Cristo puede generar rechazo, pero el discípulo responde sin venganza ni violencia. Mantiene la verdad con mansedumbre y prudencia, confiando en el Señor.", references: "Jn 15:18-20; 1 P 3:14-16"),
      StudySection(title: "41. El discernimiento frente a enseñanzas engañosas", content: "El discípulo examina toda enseñanza mediante la Escritura y no entrega su conciencia a líderes incuestionables. La fidelidad requiere comparar, preguntar y retener el evangelio apostólico.", references: "Hch 17:11; 1 Jn 4:1; Gá 1:8-9"),
      StudySection(title: "42. La relación entre conocimiento y amor", content: "El conocimiento bíblico debe producir amor y servicio. Cuando se utiliza para sentirse superior o despreciar a otros, se ha perdido su propósito formativo.", references: "1 Co 8:1-3; 1 Co 13:1-7"),
      StudySection(title: "43. La paciencia en el crecimiento espiritual", content: "El crecimiento suele desarrollarse progresivamente. El discípulo reconoce avances y áreas que necesitan madurar, evita compararse y confía en la obra continua de Dios.", references: "Fil 1:6; 2 P 3:18"),
      StudySection(title: "44. Acompañar a nuevos creyentes", content: "El acompañamiento ayuda a comprender la Biblia, integrarse a la iglesia y desarrollar hábitos de fe. Debe promover madurez y dependencia de Cristo, no control humano.", references: "1 Ts 2:7-12; Col 1:28"),
      StudySection(title: "45. La misión que nace del discipulado", content: "El discípulo participa en la misión de Cristo anunciando el evangelio con palabras y conducta. La misión busca que las personas conozcan a Jesús y aprendan a vivir según su enseñanza.", references: "Mt 5:14-16; Mt 28:19-20"),
      StudySection(title: "46. Formar discípulos en todas las naciones", content: "La orden de Jesús tiene alcance universal. La Iglesia enseña a guardar todo lo que Él mandó, respetando las culturas sin alterar el mensaje bíblico.", references: "Mt 28:18-20; Hch 1:8"),
      StudySection(title: "47. La esperanza futura del discípulo", content: "El discípulo vive con esperanza del regreso de Cristo y la consumación de su reino. Esa esperanza impulsa fidelidad, pureza y servicio en el presente.", references: "Tit 2:11-14; 1 Jn 3:2-3"),
      StudySection(title: "48. Evaluar una vida de seguimiento", content: "La madurez no se mide solo por cargos, popularidad o conocimiento acumulado. Se observa en fe, amor, obediencia, fruto del Espíritu y perseverancia.", references: "Jn 15:8; Gá 5:22-25; Stg 2:17-18"),
      StudySection(title: "49. El gozo de pertenecer a Cristo", content: "El discipulado incluye gozo y gratitud porque el creyente pertenece al Señor. Ese gozo puede coexistir con pruebas y nace de la comunión con Cristo.", references: "Jn 15:9-11; Fil 4:4-7"),
      StudySection(title: "50. Una vida entera bajo el señorío de Jesús", content: "El seguimiento de Cristo abarca todas las áreas de la existencia. El discípulo busca honrar al Señor con pensamiento, relaciones, trabajo, servicio y esperanza.", references: "Col 3:17; Ro 14:7-9"),
    ],
    conclusion: "El discipulado cristiano es una vida entera de seguimiento a Jesucristo. Comienza por la gracia de Dios, se recibe mediante la fe y se expresa en arrepentimiento, obediencia, amor, santidad, servicio y perseverancia. El Padre llama y adopta, el Hijo redime y enseña, y el Espíritu Santo habita y transforma al creyente; el único Dios obra para formar un pueblo que refleje el carácter de Cristo.\n\nLa madurez no se demuestra por títulos, popularidad o conocimiento aislado, sino por una fe que actúa mediante el amor y permanece fiel a la Palabra. La Iglesia tiene la responsabilidad de enseñar, acompañar y formar discípulos sin manipulación ni dominio humano. Cada creyente está llamado a crecer y ayudar a otros a conocer y obedecer a Jesús. Así, el discipulado une la doctrina con la vida y convierte el evangelio recibido en testimonio cotidiano para la gloria de Dios.",
  ),
Study(
    number: '86',
    title: "La iluminación del Espíritu Santo: comprensión, recepción y aplicación de las Escrituras",
    subtitle: 'La obra del Espíritu Santo para comprender, recibir y vivir conforme a la verdad revelada en la Palabra de Dios.',
    introduction: "La inspiración de las Escrituras, estudiada anteriormente, trata de la obra divina por la que la Palabra fue comunicada mediante autores humanos. Este estudio aborda una cuestión relacionada, pero distinta: cómo el Espíritu Santo ayuda a las personas a comprender y recibir esa Palabra. La Biblia enseña que el ser humano necesita la acción de Dios para discernir las verdades espirituales, y también manda leer, examinar, comparar y obedecer las Escrituras con responsabilidad.\\n\\nLa iluminación no convierte las impresiones privadas en nueva revelación normativa, no reemplaza el estudio cuidadoso y no concede infalibilidad a ningún intérprete. El Espíritu glorifica a Jesucristo, conduce a la verdad y aplica la Palabra al corazón. Desde una perspectiva trinitaria, veremos la obra del Padre que concede sabiduría, del Hijo que revela al Padre y del Espíritu Santo que enseña y transforma, sin confundir sus personas ni dividir la esencia del único Dios.",
    sections: [
      StudySection(title: "1. La diferencia entre inspiración e iluminación", content: "La inspiración se refiere a la obra por la que Dios guio a los autores humanos para comunicar su Palabra. La iluminación describe la obra del Espíritu Santo al ayudar a los lectores a comprender y recibir correctamente esa Palabra. Son doctrinas relacionadas, pero no idénticas.", references: "2 Ti 3:16; 2 P 1:20-21; 1 Co 2:12-14"),
      StudySection(title: "2. La Palabra inspirada sigue siendo la autoridad", content: "La iluminación no añade nuevos libros a la Biblia ni convierte las impresiones personales en Escritura. El Espíritu ayuda a comprender el texto que Dios ya ha dado; por eso, toda enseñanza debe someterse a la autoridad bíblica.", references: "2 Ti 3:16-17; Sal 119:160"),
      StudySection(title: "3. El Espíritu Santo es el maestro divino", content: "Jesús prometió que el Espíritu enseñaría y recordaría a sus discípulos lo que Él había dicho. Esta promesa se relaciona de manera especial con el testimonio apostólico y muestra que el Espíritu no dirige a una verdad contraria a Cristo.", references: "Jn 14:26; Jn 16:13-14"),
      StudySection(title: "4. El propósito cristocéntrico de la iluminación", content: "El Espíritu glorifica al Hijo y conduce a comprender su enseñanza. Una supuesta revelación que desplaza a Jesucristo, contradice su evangelio o niega la Palabra no puede atribuirse al Espíritu de verdad.", references: "Jn 15:26; Jn 16:14"),
      StudySection(title: "5. La necesidad humana de comprender", content: "La dificultad para recibir la verdad no se resuelve solo con capacidad intelectual. El pecado afecta el entendimiento y las inclinaciones humanas; por eso necesitamos que Dios obre en nosotros para recibir con humildad lo que comunica.", references: "1 Co 2:14; Ef 4:17-18"),
      StudySection(title: "6. El Espíritu y la mente renovada", content: "La obra del Espíritu no anula la mente, sino que transforma la manera de pensar. El creyente aprende a evaluar sus ideas, deseos y decisiones a la luz de la voluntad revelada de Dios.", references: "Ro 12:2; Ef 4:23"),
      StudySection(title: "7. El Padre concede sabiduría", content: "La Escritura presenta al Padre como aquel a quien se pide sabiduría y conocimiento espiritual. La iluminación ocurre dentro de la obra del único Dios: el Padre concede, el Hijo revela y el Espíritu enseña y aplica la verdad.", references: "Ef 1:17-18; Stg 1:5"),
      StudySection(title: "8. El Hijo revela al Padre", content: "Jesucristo es la revelación culminante de Dios. Leer la Biblia correctamente requiere atender a la manera en que toda la historia de la redención encuentra su cumplimiento en la persona y obra del Hijo.", references: "Mt 11:27; Lc 24:27; Heb 1:1-3"),
      StudySection(title: "9. El Espíritu escudriña las profundidades de Dios", content: "Pablo enseña que el Espíritu conoce las cosas profundas de Dios y que los creyentes reciben el Espíritu para conocer lo que Dios ha concedido. Esto no significa que el ser humano alcance omnisciencia, sino que depende de la revelación divina.", references: "1 Co 2:10-12"),
      StudySection(title: "10. Iluminación y lectura responsable", content: "La dependencia del Espíritu no justifica leer versículos aislados ni ignorar el contexto. La oración debe acompañar el estudio cuidadoso de las palabras, el argumento, el género literario y el lugar del pasaje en el conjunto bíblico.", references: "Neh 8:8; Lc 24:32; Hch 17:11"),
      StudySection(title: "11. El contexto histórico y literario", content: "Comprender quién habla, a quién se dirige, qué situación enfrenta y qué tipo de texto se está leyendo ayuda a evitar interpretaciones arbitrarias. El Espíritu no necesita que descuidemos los medios razonables de estudio.", references: "Lc 1:1-4; 1 Co 10:11"),
      StudySection(title: "12. La unidad de toda la Escritura", content: "Los pasajes deben interpretarse considerando el testimonio completo de la Biblia. Ninguna interpretación válida puede hacer que un texto contradiga la verdad enseñada claramente en otros pasajes.", references: "Sal 119:160; 2 P 1:20"),
      StudySection(title: "13. La oración antes y durante el estudio", content: "El creyente puede pedir que Dios abra su entendimiento, le conceda humildad y le permita obedecer lo aprendido. La oración no sustituye la lectura; expresa dependencia del Señor mientras se estudia.", references: "Sal 119:18; Ef 1:16-19"),
      StudySection(title: "14. El Espíritu y la memoria de la enseñanza de Cristo", content: "El Espíritu recordó a los apóstoles las palabras de Jesús conforme a la promesa del Señor. La Iglesia recibe ese testimonio apostólico en las Escrituras y vuelve continuamente a él para aprender de Cristo.", references: "Jn 14:26; 1 Jn 1:1-4"),
      StudySection(title: "15. Iluminación no significa nuevas doctrinas", content: "Ninguna experiencia privada tiene autoridad para corregir, completar o reemplazar la enseñanza bíblica. Las impresiones deben examinarse y nunca imponerse a otros como si tuvieran el mismo rango que la Escritura.", references: "Gá 1:8; 1 Co 4:6"),
      StudySection(title: "16. El discernimiento de las enseñanzas", content: "La Iglesia debe examinar lo que escucha, comparar las afirmaciones con la Palabra y retener lo que es bueno. La sinceridad de quien enseña no garantiza que su interpretación sea correcta.", references: "Hch 17:11; 1 Ts 5:21; 1 Jn 4:1"),
      StudySection(title: "17. La iluminación y la humildad", content: "El conocimiento bíblico no debe alimentar orgullo ni desprecio. Quien reconoce que depende de la gracia de Dios escucha, aprende, acepta corrección y evita presentarse como dueño infalible de la verdad.", references: "1 Co 8:1-2; Stg 1:19-21"),
      StudySection(title: "18. El Espíritu produce obediencia", content: "Comprender la Escritura no es acumular datos. La verdad recibida debe conducir a obedecer a Dios, abandonar el pecado y practicar la justicia, el amor y la misericordia.", references: "Jn 14:21; Stg 1:22-25"),
      StudySection(title: "19. La iluminación y la santificación", content: "El Espíritu usa la verdad de Dios para apartar al creyente para Él y formar un carácter semejante al de Cristo. La transformación cristiana no se separa de la Palabra que el Señor ha dado.", references: "Jn 17:17; 2 Co 3:18"),
      StudySection(title: "20. La comprensión del evangelio", content: "El Espíritu convence de pecado y dirige hacia la verdad acerca de Jesucristo. La comprensión salvadora del evangelio no es motivo de superioridad, sino razón para agradecer la misericordia de Dios.", references: "Jn 16:8-11; 1 Co 12:3"),
      StudySection(title: "21. La iluminación y la lectura comunitaria", content: "Dios también edifica a su pueblo mediante la enseñanza, la exhortación y el intercambio responsable entre creyentes. La comunidad no reemplaza la Escritura, sino que aprende junta bajo su autoridad.", references: "Col 3:16; Ef 4:11-16"),
      StudySection(title: "22. La función de quienes enseñan", content: "Los maestros de la Iglesia deben explicar fielmente el texto y formar a otros para manejar correctamente la Palabra. Su autoridad es ministerial y está limitada por la verdad bíblica.", references: "2 Ti 2:15; Tit 2:1"),
      StudySection(title: "23. La responsabilidad de cada creyente", content: "La dependencia del Espíritu no exime a nadie de leer y aprender. Cada creyente debe crecer en conocimiento, comprobar lo que recibe y estar preparado para dar razón de su esperanza con respeto.", references: "1 P 3:15; Heb 5:12-14"),
      StudySection(title: "24. La iluminación y los pasajes difíciles", content: "Algunos textos requieren estudio paciente, comparación y reconocimiento de los límites propios. No se debe fabricar una explicación segura cuando la información disponible no permite afirmarla.", references: "2 P 3:15-16; Pr 18:13"),
      StudySection(title: "25. El peligro de sacar textos de contexto", content: "Usar una frase bíblica para justificar una idea previa puede distorsionar el mensaje. La interpretación responsable busca lo que el pasaje comunica en su contexto, no lo que el lector desea encontrar.", references: "Mt 4:5-7; 2 Co 4:2"),
      StudySection(title: "26. El Espíritu no contradice la Escritura", content: "El Espíritu Santo es el autor divino de la Escritura y no puede guiar a una conclusión que niegue su propio testimonio. Por ello, las supuestas direcciones espirituales deben evaluarse a la luz de la Palabra.", references: "2 P 1:21; Jn 17:17"),
      StudySection(title: "27. La iluminación y la Trinidad", content: "El Padre concede sabiduría y abre el entendimiento; el Hijo es la verdad revelada y el centro del mensaje; el Espíritu Santo enseña, recuerda y aplica esa verdad. No son tres dioses ni tres modos de una sola persona, sino las tres personas del único Dios obrando inseparablemente según su relación personal.", references: "Ef 1:17-18; Jn 14:26; Jn 16:13-14"),
      StudySection(title: "28. La diferencia entre convicción y preferencia personal", content: "Una idea puede parecernos intensa o convincente sin proceder de Dios. La convicción cristiana debe estar formada por la verdad bíblica, la conciencia instruida y una evaluación humilde, no solo por emociones o deseos.", references: "Jer 17:9; Sal 19:12-14"),
      StudySection(title: "29. La iluminación y la libertad cristiana", content: "En asuntos donde la Escritura no establece un mandato específico, el creyente debe aplicar principios bíblicos con conciencia responsable, amor y sabiduría, sin convertir preferencias personales en reglas universales.", references: "Ro 14:1-13; 1 Co 10:23-24"),
      StudySection(title: "30. La Palabra como lámpara para el camino", content: "La Escritura guía las decisiones y muestra el camino de fidelidad. La iluminación permite reconocer y aplicar sus principios, pero no promete conocer anticipadamente cada detalle del futuro.", references: "Sal 119:105; 2 P 1:19"),
      StudySection(title: "31. Perseverar en el aprendizaje", content: "El crecimiento en comprensión es progresivo. El creyente debe continuar en la enseñanza apostólica, corregir errores y crecer en la gracia y el conocimiento de Jesucristo.", references: "2 P 3:18; Col 1:9-10"),
      StudySection(title: "32. La finalidad: conocer y glorificar a Dios", content: "El propósito de la iluminación no es la fama del intérprete ni la discusión interminable, sino conocer mejor a Dios, amarle, obedecerle y edificar a la Iglesia mediante la verdad.", references: "Ef 1:17-19; Col 1:9-12; 1 Co 10:31")
    ],
    conclusion: "La iluminación del Espíritu Santo es la ayuda divina por la cual los creyentes comprenden y reciben la verdad de las Escrituras. No agrega autoridad a la Biblia ni permite contradecirla; impulsa a leer con atención, interpretar en contexto, examinar toda enseñanza y obedecer lo que Dios ha revelado. La dependencia del Espíritu y el estudio responsable no compiten: se complementan.\\n\\nEsta obra pertenece al único Dios trino: el Padre concede sabiduría y abre el entendimiento, el Hijo es la revelación culminante y el centro del mensaje, y el Espíritu Santo enseña, recuerda y aplica la verdad. El resultado esperado es una fe más firme, un carácter transformado, amor por Cristo y edificación de la Iglesia para la gloria de Dios."
  ),
Study(
    number: '87',
    title: "La regeneración espiritual: el nuevo nacimiento y la obra vivificadora del Espíritu Santo",
    subtitle: 'La vida nueva que Dios concede por su gracia mediante Jesucristo y por la obra del Espíritu Santo.',
    introduction: "La regeneración espiritual es la obra de Dios por la que una persona recibe vida nueva. Jesús enseñó que es necesario nacer de nuevo para ver el reino de Dios. Esta necesidad no se resuelve con religión externa, tradición familiar, conocimiento intelectual ni esfuerzo moral: el ser humano necesita que Dios renueve su interior.\\n\\nEste estudio distingue la regeneración de otros aspectos de la salvación ya tratados en el catálogo. La justificación habla del veredicto de Dios; la adopción, de la nueva condición filial; la conversión, de la respuesta de arrepentimiento y fe; la santificación, del crecimiento en santidad. La regeneración se concentra en el nuevo nacimiento y la vida espiritual que Dios concede. Desde la doctrina trinitaria, examinaremos la obra unida del Padre, del Hijo y del Espíritu Santo, sin confundir sus personas ni dividir la única esencia divina.",
    sections: [
      StudySection(title: "1. El significado bíblico de la regeneración", content: "Regenerar significa dar nueva vida. En el lenguaje de Jesús, esta realidad se expresa como nacer de nuevo o nacer de arriba: una obra de Dios por la que la persona recibe vida espiritual y entra en una nueva relación con Él.", references: "Jn 3:3-8; Tit 3:5"),
      StudySection(title: "2. La necesidad del nuevo nacimiento", content: "Jesús enseñó que nadie puede ver el reino de Dios sin nacer de nuevo. La necesidad no se limita a corregir hábitos externos; el ser humano necesita una renovación profunda que no puede producir por sus propias fuerzas.", references: "Jn 3:3; Ef 2:1-5"),
      StudySection(title: "3. La condición humana sin la gracia", content: "La Escritura describe al ser humano afectado por el pecado y necesitado de vida procedente de Dios. Esta condición explica por qué la regeneración es una obra divina y no un logro moral o religioso.", references: "Ef 2:1-3; Ro 3:9-18"),
      StudySection(title: "4. El nuevo nacimiento procede de Dios", content: "Los hijos de Dios no nacen espiritualmente por voluntad humana, ascendencia, tradición ni capacidad personal. La vida nueva tiene su origen en la misericordia y el poder de Dios.", references: "Jn 1:12-13; Stg 1:18"),
      StudySection(title: "5. La obra del Espíritu Santo", content: "Jesús relaciona el nuevo nacimiento con el Espíritu. La regeneración no es una simple emoción ni una reforma superficial: es una obra del Espíritu que da vida y produce una nueva disposición hacia Dios.", references: "Jn 3:5-8; Tit 3:5-6"),
      StudySection(title: "6. Agua y Espíritu en Juan 3", content: "La referencia al agua y al Espíritu recuerda la promesa profética de limpieza y renovación interior. Jesús llama a Nicodemo a comprender que la entrada al reino requiere la transformación prometida por Dios, no solo conocimiento religioso.", references: "Jn 3:5; Ez 36:25-27"),
      StudySection(title: "7. La promesa de un corazón nuevo", content: "Por medio de los profetas, Dios prometió limpiar a su pueblo, quitar el corazón de piedra y dar un corazón nuevo. La regeneración se comprende dentro de esta promesa de restauración interior.", references: "Ez 11:19-20; Ez 36:26-27"),
      StudySection(title: "8. La acción vivificadora del Padre", content: "La Escritura presenta al Padre como fuente de misericordia y autor del propósito salvador. Él da vida conforme a su voluntad y hace nacer a sus hijos por su Palabra de verdad.", references: "Ef 2:4-5; Stg 1:17-18"),
      StudySection(title: "9. La vida nueva por medio del Hijo", content: "Jesucristo es la vida y quien cree en Él recibe vida eterna. La regeneración no puede separarse de la persona y obra del Hijo, porque la vida que Dios concede está unida a Cristo.", references: "Jn 1:4; Jn 5:21; 1 Jn 5:11-12"),
      StudySection(title: "10. La regeneración y la Trinidad", content: "El Padre concede vida conforme a su misericordia, el Hijo es la vida manifestada y el fundamento de la salvación, y el Espíritu Santo realiza la renovación interior. Las tres personas obran en perfecta unidad divina, sin confundirse entre sí.", references: "Jn 3:5-8; Jn 5:21; Tit 3:4-6; 1 P 1:3"),
      StudySection(title: "11. Nacer de nuevo no es reencarnación", content: "La expresión bíblica del nuevo nacimiento no enseña que el alma regrese a otro cuerpo ni que una persona tenga varias vidas terrenales. Describe una transformación espiritual que ocurre por la gracia de Dios.", references: "Jn 3:3-8; Heb 9:27"),
      StudySection(title: "12. No es una segunda naturaleza divina", content: "La regeneración no convierte al creyente en Dios ni lo hace partícipe de la esencia divina. La persona sigue siendo criatura, pero recibe vida espiritual y participa de las promesas de Dios por gracia.", references: "2 P 1:3-4; 1 Co 8:6"),
      StudySection(title: "13. La relación entre regeneración y conversión", content: "La regeneración es la obra vivificadora de Dios; la conversión describe la respuesta humana de arrepentimiento y fe. Son realidades estrechamente relacionadas, pero no significan exactamente lo mismo.", references: "Hch 3:19; Jn 3:3-8; Ef 2:8-10"),
      StudySection(title: "14. La fe y la vida nueva", content: "La fe recibe a Jesucristo y confía en Él. La regeneración no debe presentarse como mérito humano, sino como gracia divina que produce una respuesta real de confianza en el Salvador.", references: "Jn 1:12-13; Ef 2:8-9"),
      StudySection(title: "15. El arrepentimiento y el nuevo nacimiento", content: "La vida nueva no hace innecesario el arrepentimiento. Quien vuelve a Dios reconoce el pecado, abandona su camino y busca vivir bajo el señorío de Jesucristo.", references: "Hch 2:37-38; Hch 3:19"),
      StudySection(title: "16. La Palabra como instrumento de vida", content: "Dios hace nacer por la palabra de verdad y la semilla incorruptible de su Palabra. El mensaje del evangelio anuncia a Cristo y es usado por Dios para llamar a las personas a la fe.", references: "Stg 1:18; 1 P 1:23-25"),
      StudySection(title: "17. La regeneración y la justificación", content: "La justificación se refiere al veredicto de Dios que declara justo al que cree en Cristo; la regeneración se refiere a la nueva vida interior. No deben confundirse, aunque ambas pertenecen a la obra salvadora de Dios.", references: "Ro 3:24-26; Tit 3:5-7"),
      StudySection(title: "18. La regeneración y la adopción", content: "La nueva vida se relaciona con la entrada en la familia de Dios, pero la regeneración y la adopción destacan aspectos distintos: vida espiritual concedida y nueva condición filial recibida por gracia.", references: "Jn 1:12-13; Ro 8:15-16"),
      StudySection(title: "19. Una nueva creación", content: "En Cristo, el creyente es hecho nueva creación. Esta expresión señala que la gracia de Dios inaugura una existencia renovada, orientada hacia la reconciliación y las buenas obras.", references: "2 Co 5:17-18; Ef 2:10"),
      StudySection(title: "20. La transformación de los deseos", content: "El nuevo nacimiento cambia la orientación del corazón. El creyente comienza a amar lo que agrada a Dios y a rechazar el pecado, aunque todavía necesita crecer y luchar contra sus inclinaciones pecaminosas.", references: "Ez 36:26-27; Gá 5:16-17"),
      StudySection(title: "21. La regeneración no significa perfección inmediata", content: "La vida nueva no implica que el creyente alcance de inmediato una conducta impecable. La Escritura llama a crecer, confesar los pecados y caminar diariamente en obediencia por la gracia de Dios.", references: "1 Jn 1:8-9; Fil 3:12-14"),
      StudySection(title: "22. El fruto visible de la vida nueva", content: "La regeneración se manifiesta progresivamente en amor, justicia, obediencia y una relación diferente con el pecado. Las obras no compran la vida nueva; evidencian la transformación que Dios produce.", references: "1 Jn 2:29; 1 Jn 3:9-10; Gá 5:22-23"),
      StudySection(title: "23. Amor a los hermanos", content: "El amor fraternal es una señal importante de la vida procedente de Dios. No se limita a palabras, sino que se expresa en servicio, compasión, perdón y cuidado sincero.", references: "1 Jn 4:7-12; 1 Jn 3:14-18"),
      StudySection(title: "24. La victoria sobre el dominio del pecado", content: "El creyente ya no debe vivir sometido al pecado como señor. La gracia lo llama a considerarse unido a Cristo y a presentar su vida al servicio de la justicia.", references: "Ro 6:4-14; Ro 8:1-4"),
      StudySection(title: "25. La obra continua de santificación", content: "La regeneración inaugura la vida nueva; la santificación describe el crecimiento en semejanza a Cristo. El Espíritu continúa formando al creyente mediante la Palabra, la comunión y la obediencia.", references: "2 Co 3:18; 1 Ts 4:3; 1 P 1:2"),
      StudySection(title: "26. La seguridad y la evidencia de la vida nueva", content: "La confianza cristiana descansa en las promesas de Dios y en la obra de Cristo. El fruto espiritual ofrece evidencia para examinar la vida, pero no debe convertirse en una búsqueda obsesiva de perfección ni en motivo de orgullo.", references: "Jn 10:27-29; 1 Jn 5:11-13; 2 P 1:5-10"),
      StudySection(title: "27. La regeneración y la perseverancia", content: "Quien ha recibido vida de Dios es llamado a permanecer en Cristo y continuar en la fe. La perseverancia no es autosuficiencia, sino dependencia de la gracia y fidelidad de Dios.", references: "Col 1:21-23; Fil 1:6; 1 P 1:5"),
      StudySection(title: "28. La diferencia entre emoción y regeneración", content: "Una experiencia intensa, una decisión pública o una emoción religiosa no demuestran por sí solas el nuevo nacimiento. La evaluación debe considerar la confianza en Cristo y el fruto de una vida transformada conforme a la Escritura.", references: "Mt 7:21-23; Jn 3:3; 1 Jn 2:3-6"),
      StudySection(title: "29. La regeneración y la vida de la Iglesia", content: "Quienes han recibido vida en Cristo son incorporados a un pueblo que aprende, sirve y se edifica mutuamente. La comunidad cristiana debe acompañar el crecimiento sin sustituir la obra que solo Dios puede realizar en el corazón.", references: "Hch 2:41-47; 1 Co 12:12-13"),
      StudySection(title: "30. El testimonio del nuevo nacimiento", content: "La vida regenerada debe dar testimonio de la gracia de Dios mediante palabras y conducta. El creyente anuncia a Cristo sin atribuirse el poder de producir la regeneración en otros.", references: "Mt 5:14-16; 1 P 2:9-12"),
      StudySection(title: "31. La esperanza de la vida eterna", content: "La regeneración está vinculada con la esperanza que Dios concede por medio de Jesucristo. La vida nueva comienza ahora y mira hacia la herencia eterna que será plenamente manifestada.", references: "Tit 3:5-7; 1 P 1:3-5"),
      StudySection(title: "32. Vivir conforme a la nueva vida", content: "La respuesta apropiada es caminar en novedad de vida: confiar en Cristo, depender del Espíritu, amar a los hermanos, obedecer la Palabra y dar gloria al Padre. La regeneración es gracia que transforma la existencia entera.", references: "Ro 6:4; Gá 5:25; Col 3:1-17")
    ],
    conclusion: "La regeneración es la obra misericordiosa de Dios que concede vida espiritual al ser humano. No es reencarnación, reforma superficial ni logro humano. El nuevo nacimiento procede de Dios, está inseparablemente relacionado con Jesucristo y es realizado por el Espíritu Santo. Sus efectos se manifiestan en una nueva orientación del corazón, fe en Cristo, amor a los hermanos, rechazo del pecado y crecimiento en santidad.\\n\\nLa regeneración debe distinguirse de la justificación, la adopción, la conversión y la santificación, aunque todas estas verdades pertenecen a la salvación. En la obra del único Dios trino, el Padre concede vida conforme a su misericordia, el Hijo es nuestra vida y salvación, y el Espíritu renueva el interior. Por tanto, toda gloria pertenece a Dios, y quien ha recibido vida nueva es llamado a caminar en obediencia, esperanza y amor."
  ),
Study(
    number: '88',
    title: "La unión con Cristo: fundamento de la identidad y de los beneficios de la salvación",
    subtitle: "La relación salvadora con Jesucristo: pertenencia, vida nueva y participación por gracia en sus beneficios.",
    introduction: "La Biblia describe repetidamente a los creyentes como personas que están «en Cristo». Esta expresión reúne una verdad central del evangelio: quienes confían en Jesús pertenecen a Él, reciben los beneficios de su obra y son llamados a vivir bajo su señorío. La unión con Cristo no es una fusión de identidades ni convierte al creyente en Dios; es una relación espiritual establecida por la gracia divina.\\n\\nEste estudio aborda la unión con Cristo como una dimensión propia de la salvación, distinta aunque estrechamente relacionada con la justificación, la adopción, la regeneración y la santificación ya estudiadas. También examina la obra del Padre, del Hijo y del Espíritu Santo: el Padre concede las bendiciones en su Hijo, Jesucristo realiza la redención y el Espíritu Santo aplica la obra divina y habita en el creyente. Las tres personas son distintas y obran en perfecta unidad como el único Dios.",
    sections: [
      StudySection(title: "1. El significado de estar en Cristo", content: "La expresión «en Cristo» describe una relación espiritual real con Jesucristo: el creyente pertenece a Él, recibe los beneficios de su obra y vive bajo su señorío. No significa que la persona pierda su identidad ni que se convierta en parte de la esencia divina.", references: "Ro 8:1; 2 Co 5:17; Ef 1:3-4"),
      StudySection(title: "2. Una realidad central del evangelio", content: "La unión con Cristo no es un detalle secundario, sino una manera bíblica de explicar cómo la salvación llega a las personas. Dios no solo concede beneficios aislados: incorpora al creyente a una relación viva con su Hijo.", references: "Jn 15:4-5; Ef 1:3-7; Col 2:9-10"),
      StudySection(title: "3. El fundamento está en la gracia de Dios", content: "Esta unión tiene su origen en el propósito misericordioso de Dios, no en una iniciativa humana que obligue al Señor. La salvación nace de la gracia y conduce a una vida de gratitud y obediencia.", references: "Ef 1:4-6; 2:4-10; 2 Ti 1:9"),
      StudySection(title: "4. La obra del Padre", content: "El Padre llama, elige conforme a su propósito y concede al creyente toda bendición espiritual en Cristo. La relación con el Hijo no elimina la distinción personal entre el Padre y el Hijo.", references: "Jn 6:37-40; Ef 1:3-6; 1 P 1:2"),
      StudySection(title: "5. La obra del Hijo", content: "Jesucristo es el mediador y fundamento de esta unión. Por su encarnación, muerte y resurrección, abre el camino de reconciliación y vida para quienes creen en Él.", references: "Ro 5:8-11; Ef 2:13-18; Col 1:19-22"),
      StudySection(title: "6. La obra del Espíritu Santo", content: "El Espíritu Santo hace efectiva la obra de Dios en el creyente, lo incorpora al cuerpo de Cristo y habita en él. Su presencia no es la de una fuerza impersonal, sino la del Espíritu divino que glorifica a Cristo.", references: "Jn 14:16-17; 1 Co 12:13; Ef 1:13-14"),
      StudySection(title: "7. La unión con Cristo y la Trinidad", content: "La salvación procede del único Dios trino: el Padre establece su propósito, el Hijo realiza la redención y el Espíritu aplica sus beneficios. Las personas actúan inseparablemente en la única obra divina, sin confundirse entre sí.", references: "Ef 1:3-14; 1 P 1:2; 2 Co 13:14"),
      StudySection(title: "8. La unión no confunde al creyente con Cristo", content: "Estar unido a Cristo no significa que el creyente se vuelva Jesucristo, que comparta su identidad personal o que se convierta en Dios. La relación es por gracia: Cristo sigue siendo el Señor y el creyente permanece criatura redimida.", references: "Jn 17:20-23; 1 Co 6:17; 2 P 1:4"),
      StudySection(title: "9. La imagen de la vid y los pámpanos", content: "Jesús compara la relación con Él con una vid y sus ramas. La rama depende de la vid para dar fruto; de igual manera, el discípulo necesita permanecer en Cristo y depender de su palabra y gracia.", references: "Jn 15:1-8"),
      StudySection(title: "10. Permanecer en Cristo", content: "Permanecer en Cristo implica continuar confiando en Él, guardar su palabra y vivir en comunión con Él. No es una experiencia momentánea ni una fórmula verbal, sino una relación perseverante que se expresa en obediencia y amor.", references: "Jn 8:31; 15:4-10; 1 Jn 2:24-28"),
      StudySection(title: "11. Participación en su muerte", content: "La Escritura enseña que el creyente ha sido unido a Cristo en la semejanza de su muerte. Esto significa que la obra de la cruz determina su nueva relación con el pecado y con la antigua manera de vivir.", references: "Ro 6:3-6; Gá 2:20"),
      StudySection(title: "12. Participación en su resurrección", content: "Así como Cristo resucitó, quienes están en Él reciben una vida nueva y esperan la resurrección final. La unión con Cristo conecta la existencia presente del creyente con la victoria futura del Señor.", references: "Ro 6:4-11; Ef 2:4-6; Col 3:1-4"),
      StudySection(title: "13. La unión y la justificación", content: "La justificación es el veredicto por el cual Dios declara justo al que cree en Cristo. La unión explica la relación con el Hijo en quien se recibe esa justicia; ambos conceptos se relacionan, pero no son sinónimos.", references: "Ro 3:21-26; 5:1; 8:1"),
      StudySection(title: "14. La unión y la adopción", content: "Por medio de Jesucristo, los creyentes reciben condición de hijos de Dios. Cristo es el Hijo por naturaleza; los creyentes son adoptados por gracia y reciben el Espíritu de adopción.", references: "Jn 1:12-13; Gá 4:4-7; Ef 1:5"),
      StudySection(title: "15. La unión y la regeneración", content: "La regeneración destaca el nuevo nacimiento que Dios concede. La unión con Cristo destaca la relación con el Salvador en quien se recibe vida nueva. Son aspectos relacionados de la salvación, no doctrinas intercambiables.", references: "Jn 3:3-8; 2 Co 5:17; Ef 2:5-6"),
      StudySection(title: "16. La unión y la santificación", content: "La santificación describe la consagración y el crecimiento en santidad. La unión con Cristo es fundamento de esa transformación: el creyente aprende a vivir de acuerdo con la nueva identidad que ha recibido en Él.", references: "1 Co 1:2; 6:11; Heb 10:10; 1 Ts 4:3"),
      StudySection(title: "17. Una nueva identidad", content: "La identidad cristiana no depende principalmente de logros, posición social o pasado, sino de pertenecer a Cristo. Esta verdad produce humildad, seguridad y responsabilidad para vivir de manera coherente con el evangelio.", references: "Gá 3:26-29; Col 3:1-4; 1 P 2:9-10"),
      StudySection(title: "18. Libertad del dominio del pecado", content: "La unión con Cristo cambia la relación del creyente con el pecado: ya no debe obedecerlo como señor. Esta libertad no significa ausencia inmediata de lucha, sino una nueva pertenencia que llama a vivir para Dios.", references: "Ro 6:6-14; Gá 5:1"),
      StudySection(title: "19. Cristo vive en el creyente", content: "Pablo habla de Cristo viviendo en él. Esta expresión describe la presencia y dirección de Cristo en la vida del creyente por el Espíritu, sin borrar la personalidad humana ni convertir al cristiano en una persona divina.", references: "Gá 2:20; Ef 3:16-17; Col 1:27"),
      StudySection(title: "20. La fe como medio de recepción", content: "La unión con Cristo se recibe por la fe, que descansa en la persona y obra de Jesús. La fe no compra la salvación ni constituye un mérito; recibe lo que Dios concede por gracia.", references: "Jn 1:12; Gá 2:16; Ef 2:8-9"),
      StudySection(title: "21. La unión y la obediencia", content: "La obediencia no es el precio para entrar en Cristo, sino fruto de pertenecerle. Quien confiesa a Jesús como Señor está llamado a someter sus decisiones, palabras y acciones a su enseñanza.", references: "Jn 14:15; Ro 6:17-18; 1 Jn 2:3-6"),
      StudySection(title: "22. El amor como fruto de la unión", content: "La comunión con Cristo produce amor hacia Dios y hacia los demás. El amor cristiano no se reduce a sentimiento: se expresa en servicio, verdad, perdón y cuidado concreto del prójimo.", references: "Jn 13:34-35; 15:9-13; 1 Jn 4:7-12"),
      StudySection(title: "23. La unión y la oración", content: "La relación con Cristo da confianza para acercarse al Padre. La oración cristiana se dirige al Padre, por medio del Hijo y en la ayuda del Espíritu, respetando la distinción personal que enseña la Escritura.", references: "Jn 16:23-27; Ef 2:18; Ro 8:26-27"),
      StudySection(title: "24. La unión y la Iglesia", content: "Quienes pertenecen a Cristo forman un solo cuerpo con diversidad de miembros. La unión con el Señor no fomenta aislamiento individualista, sino comunión, servicio mutuo y edificación de la Iglesia.", references: "Ro 12:4-5; 1 Co 12:12-27; Ef 4:15-16"),
      StudySection(title: "25. Unidad sin uniformidad", content: "La unidad de los creyentes no exige que todos tengan la misma función, personalidad o capacidad. En Cristo hay diversidad de dones y responsabilidades que deben contribuir al bien común.", references: "Ro 12:6-8; 1 Co 12:4-7; Ef 4:1-6"),
      StudySection(title: "26. La Cena del Señor y la comunión", content: "La Cena anuncia la muerte de Cristo y expresa la comunión del pueblo redimido con Él. No debe confundirse el signo sacramental con una repetición del sacrificio único de Jesús.", references: "1 Co 10:16-17; 11:23-26; Heb 10:10-14"),
      StudySection(title: "27. La unión y el sufrimiento", content: "Estar unido a Cristo no garantiza ausencia de dificultades. El creyente puede sufrir por causa de la fe, pero encuentra consuelo en la presencia del Señor y esperanza en la gloria que será revelada.", references: "Ro 8:17-18; Fil 1:29; 1 P 4:13"),
      StudySection(title: "28. Seguridad y perseverancia", content: "La confianza del creyente descansa en la fidelidad de Dios y en la suficiencia de Cristo. Esta seguridad llama a permanecer en la fe y no debe utilizarse como excusa para vivir deliberadamente en desobediencia.", references: "Jn 10:27-30; Ro 8:31-39; Col 1:21-23"),
      StudySection(title: "29. La esperanza de estar con Cristo", content: "La unión con Cristo no termina en la vida presente. La esperanza cristiana incluye estar con el Señor y participar de la resurrección y gloria que Él ha prometido a los suyos.", references: "Jn 14:1-3; Fil 3:20-21; 1 Ts 4:16-17"),
      StudySection(title: "30. Vivir cada día en Cristo", content: "La doctrina debe conducir a una vida concreta: depender de Cristo, escuchar su palabra, andar por el Espíritu, amar a la Iglesia y dar gloria al Padre. La unión con Cristo es fundamento de identidad, comunión, servicio y esperanza.", references: "Col 2:6-7; 3:12-17; Gá 5:16, 22-25")
    ],
    conclusion: "La unión con Cristo describe la relación por gracia mediante la cual el creyente pertenece al Salvador y recibe en Él vida, identidad, comunión y esperanza. No significa que el cristiano se convierta en Cristo ni que participe de la esencia divina. Cristo permanece como el Hijo eterno y Señor; el creyente permanece como criatura redimida que depende de Él.\\n\\nEsta verdad se relaciona con la justificación, adopción, regeneración y santificación, pero no las reemplaza ni las confunde. El Padre nos bendice en su Hijo, Jesucristo realizó la obra redentora y el Espíritu Santo nos incorpora al cuerpo de Cristo y produce fruto en nosotros. Por tanto, estar en Cristo llama a permanecer en su palabra, andar en obediencia, amar a los hermanos, servir a la Iglesia y esperar su venida. Toda la gloria pertenece al único Dios: Padre, Hijo y Espíritu Santo.",
  ),
];
